// Üretilen dosya: tool/ozgun/uret.py. Tarih · Denizcilik tarihi, boğazlar, kanallar, ünlü denizciler ve deniz muharebeleri (Fenikeliler, Piri Reis, Barbaros, Preveze, İnebahtı, Trafalgar, Süveyş, Panama) (orta).
const ozHistory16Orta = <(String, String, List<String>, String)>[
  ('MÖ 480 yılında Atina\'nın tahliye edilmesinin ardından dar boğazda Pers İmparatorluğu\'nun sayıca üstün donanmasını ağır yenilgiye uğratan Yunan deniz stratejisti kimdir?', 'Themistokles', ['Leonidas', 'Perikles', 'Alkibiades'], 'Themistokles, gümüş madenlerinden elde edilen gelirle Atina donanmasını güçlendirmiş ve Salamis Boğazı\'nda Pers filosunu tuzağa düşürmüştür.'),
  ('Birinci Pön Savaşı sırasında denizcilik tecrübesi az olan Romalıların, deniz muharebesini kara savaşına dönüştürmek için gemi pruvalarına yerleştirdikleri kancalı rampa düzeneği nedir?', 'Corvus', ['Ballista', 'Onager', 'Testudo'], 'Corvus (karga) adı verilen döner köprü, düşman gemisinin güvertesine saplanarak Roma lejyonerlerinin karşı gemiye geçmesini sağlamıştır.'),
  ('655 yılında Doğu Akdeniz\'de Bizans İmparatoru II. Konstans komutasındaki donanmayı mağlup ederek Müslümanların Akdeniz\'deki ilk büyük deniz zaferini kazandığı çarpışma hangisidir?', 'Zâtü\'s-Savârî Savaşı', ['Yermük Muharebesi', 'Kadisiye Savaşı', 'Ecnâdeyn Muharebesi'], 'Gemi direklerinin çokluğundan dolayı \'Direkler Savaşı\' (Zâtü\'s-Savârî) olarak anılan bu muharebe Bizans\'ın Doğu Akdeniz tekelini kırmıştır.'),
  ('Girit Adası merkezli olarak MÖ 2000\'li yıllarda Ege\'de güçlü bir ticaret filosu kuran ve tarihte bilinen ilk talassokrasi (deniz imparatorluğu) örneği sayılan uygarlık hangisidir?', 'Minos Uygarlığı', ['Miken Uygarlığı', 'Lidya Krallığı', 'Urartu Devleti'], 'Minos saraylarının sursuz inşa edilmesi, Giritlilerin güvenliklerini güçlü donanmalarına dayandırdıklarının kanıtı kabul edilir.'),
  ('Denizde fırtınaya yakalanan bir gemiyi kurtarmak için denize atılan yüklerin zararının gemi sahibi ve tüm yük sahiplerince ortaklaşa paylaşılması ilkesi hangi antik hukuk metnine dayanır?', 'Rodos Deniz Yasası', ['Hammurabi Kanunları', 'Drakon Yasaları', 'On İki Levha Kanunları'], 'Lex Rhodia de iactu (müşterek avarya kuralı), Rodos denizcilerinin oluşturduğu ve Roma hukuku üzerinden modern deniz hukukuna geçen ilkedir.'),
  ('Dördüncü Haçlı Seferi haçlı ordusunu taşıma bedeli karşılığında önce Zara kentini, ardından 1204\'te Konstantinopolis\'i ele geçirmeye yönlendiren Venedik Doju kimdir?', 'Enrico Dandolo', ['Andrea Doria', 'Simone Boccanegra', 'Pietro Orseolo'], 'İleri yaşına ve görme engeline rağmen donanmaya bizzat komuta eden Enrico Dandolo, Venedik\'in Ege ve Marmara\'da üsler kurmasını sağlamıştır.'),
  ('Venedik Cumhuriyeti\'nde savaş kadırgalarının standart parçalarla seri üretim mantığıyla donatıldığı ve Avrupa\'nın sanayi öncesi en büyük tersane kompleksi kabul edilen kurum hangisidir?', 'Venedik Arsenale Tersanesi', ['Cenova San Giorgio Bankası', 'Pisa Tersane Kulesi', 'Livorno Serbest Limanı'], 'Venedik Arsenale\'de kadırgalar bir kanal boyunca ilerlerken farklı istasyonlarda direk, yelken ve silahlarla birkaç saat içinde donatılabiliyordu.'),
  ('Vikinglerin savaşta kullandıkları uzun ve dar drakkarların aksine, Atlantik geçişlerinde göçmen, hayvan ve ticari yük taşımak için kullandıkları daha geniş gövdeli yelkenli gemi hangisidir?', 'Knarr', ['Bireme', 'Firkateyn', 'Şebek'], 'Knarr tipi gemiler derin su çekimi ve geniş ambar hacmiyle İzlanda, Grönland ve Vinland kolonilerinin lojistiğini sağlamıştır.'),
  ('Hint Okyanusu ve Basra Körfezi denizcilerinin yüzyıllar boyunca muson rüzgârlarıyla seyir yaparken kullandıkları, gövde tahtaları çivi yerine Hindistan cevizi lifleriyle dikilen üçgen yelkenli gemi nedir?', 'Dhow', ['Sampan', 'Cunk', 'Uru'], 'Arap ve Hint Okyanusu denizciliğinin simgesi olan Dhow (Dav) gemileri, üçgen latin yelkenleriyle rüzgâra yakın seyir yapabilmiştir.'),
  ('Bizans İmparatorluğu donanmasının belkemiğini oluşturan, tek veya çift sıra kürekli, latin yelkenli ve pruvasında Rum ateşi sifonu taşıyan hızlı savaş gemisi türü hangisidir?', 'Dromon', ['Galeon', 'Korvet', 'Uşkuna'], 'Yunanca \'koşucu\' anlamına gelen Dromon, antik triremelerin yerini alarak 6. yüzyıldan 12. yüzyıla dek Bizans deniz gücünü temsil etmiştir.'),
  ('MÖ 6. yüzyılda Mısır Firavunu II. Neko\'nun Nil Nehri ile Kızıldeniz\'i birleştiren bir kanal kazdırması ve Fenikeli gemicileri Afrika kıtasını dolaşmakla görevlendirmesi hangi tarihçinin eserinde aktarılır?', 'Herodotos', ['Thukydides', 'Polybios', 'Plutarkhos'], 'Herodotos, Fenikeli denizcilerin Kızıldeniz\'den çıkıp Güney Yarımküre\'de Güneş\'i sağ taraflarında görerek üç yılda Akdeniz\'e döndüklerini kaydeder.'),
  ('1592-1598 Imjin Savaşı\'nda Japon istila filosuna karşı üstü demir dikenli levhalarla kaplı \'Geobukseon\' (Kaplumbağa Gemisi) adlı zırhlı gemileri etkin biçimde kullanan Koreli amiral kimdir?', 'Yi Sun-sin', ['Toyotomi Hideyoshi', 'Kubilay Han', 'Jeongjo'], 'Amiral Yi Sun-sin, Myeongnyang ve Hansando muharebelerinde akıntıları ve kaplumbağa gemilerini kullanarak sayıca çok üstün Japon donanmasını yenmiştir.'),
  ('Orta Çağ\'da Venedik Doju\'nun her yıl Yükseliş Yortusu\'nda \'Bucintoro\' adlı tören gemisiyle denize altın yüzük atarak gerçekleştirdiği sembolik tören neyi ifade ederdi?', 'Venedik\'in Adriyatik Denizi ile evliliğini', ['Bizans İmparatoru\'na bağlılık yeminini', 'Haçlı donanmalarının uğurlanmasını', 'Tersane işçilerinin lonca kabulünü'], '\'Sposalizio del Mare\' (Denizle Evlilik) töreni, Venedik Cumhuriyeti\'nin Adriyatik suları üzerindeki mutlak egemenlik iddiasını simgeliyordu.'),
  ('MÖ 480 yılında Pers Kralı Kserkses\'in ordusunu Anadolu\'dan Avrupa yakasına geçirmek amacıyla Çanakkale Boğazı\'nın en dar yerinde yan yana bağlattığı yüzlerce gemiyle kurduğu yapı nedir?', 'Abidos-Sestos yüzer gemi köprüsü', ['Athos Yarımadası kanalı', 'Korint gemi kızak yolu', 'Halikarnas dalgakıranı'], 'Kserkses, fırtınanın ilk köprüyü parçalaması üzerine fenikeli ve Mısırlı mühendislere keten ve papirüs halatlarla tutturulan çift sıra gemi köprüsü kurdurmuştur.'),
  ('Çin gemi inşa geleneğinde \'Cunk\' (Junk) adı verilen gemilerin okyanus fırtınalarında bir yerden su alsa bile tamamen batmasını önleyen ve sonradan Batı gemilerine uyarlanan yapısal yenilik nedir?', 'Su geçirmez bölmeli gövde', ['Bakır kaplamalı karina', 'Buharlı çark sistemi', 'Çift pruva mahmuzu'], 'Marco Polo\'nun da hayranlıkla aktardığı su geçirmez dikey perdeler (bulkhead), Çin gemilerinin gövde sağlamlığını ve batmazlığını artırmıştır.'),
  ('MÖ 1200\'lü yıllarda Doğu Akdeniz kıyı kentlerini, Kıbrıs\'ı ve Hitit ticaret yollarını sarsan, Mısır Firavunu III. Ramses\'in Nil Deltası\'ndaki deniz muharebesiyle durdurabildiği topluluklar nasıl adlandırılır?', 'Deniz Kavimleri', ['İskit Atlıları', 'Kimmer Göçebeleri', 'Hyksos Hanedanı'], 'Medinet Habu Tapınağı duvarlarında tasvir edilen Nil Deltası Muharebesi, Tunç Çağı çöküşünde rol oynayan Deniz Kavimleri\'ne karşı kazanılmış büyük bir deniz zaferidir.'),
  ('Cenevizlilerin Karadeniz kuzeyindeki Kırım Yarımadası\'nda kurdukları ve İpek Yolu\'nun batı ucundaki en önemli deniz antreposu haline getirdikleri liman kenti hangisidir?', 'Kefe', ['Varna', 'Köstence', 'Batum'], 'Kefe (Feodosiya), Ceneviz\'in Karadeniz\'deki başkonsolosluk merkezi olmuş, 1475\'te Gedik Ahmet Paşa komutasındaki Osmanlı donanmasınca fethedilmiştir.'),
  ('Roma İmparatorluğu\'nda Akdeniz\'deki korsanlığı temizledikten sonra İtalya yarımadasının batı ve doğu denizlerini korumak üzere Misenum ve Ravenna\'da kalıcı donanma üsleri kuran ilk imparator kimdir?', 'Augustus', ['Neron', 'Caligula', 'Konstantin'], 'İmparator Augustus, Classis Misenensis ve Classis Ravennas adıyla Roma\'nın sürekli profesyonel imparatorluk donanmalarını teşkilatlandırmıştır.'),
  ('MÖ 67 yılında Roma Senatosu\'ndan aldığı olağanüstü yetkiyle Akdeniz\'i 13 bölgeye ayırıp Kilikya korsanlarını yalnızca üç ay içinde etkisiz hale getiren Romalı komutan kimdir?', 'Pompeius', ['Crassus', 'Sulla', 'Marius'], 'Lex Gabinia yasasıyla Akdeniz ve kıyılarında tam yetki alan Gnaeus Pompeius Magnus, koordineli bir süpürme harekâtıyla korsan üslerini çökertmiştir.'),
  ('Viking denizcilerinin dokuzuncu yüzyıldan itibaren Baltık Denizi\'nden girip Dinyeper ve Volga gibi nehir sistemlerini izleyerek Karadeniz ile Konstantinopolis\'e ulaştıkları ticaret güzergâhı nasıl adlandırılır?', 'Vareglerden Yunanlara uzanan yol', ['Kral Yolu ticaret hattı', 'Kehribar Kervan Yolu', 'Kuzeybatı Buzul Geçidi'], 'Doğu Slav kroniklerinde \'Vareglerden Yunanlara uzanan su yolu\' olarak geçen bu nehir-deniz hattı Kiev Knezliği\'nin kuruluşuna zemin hazırlamıştır.'),
  ('5. yüzyılda Kuzey Afrika\'daki Kartaca\'yı ele geçirip güçlü bir donanma kurarak Batı Akdeniz adalarını alan ve 455\'te deniz yoluyla Roma\'yı yağmalayan Cermen kavmi hangisidir?', 'Vandallar', ['Vizigotlar', 'Ostrogotlar', 'Lombardlar'], 'Kral Genserik önderliğindeki Vandallar, diğer Cermen kavimlerinin aksine büyük bir donanma inşa ederek Batı Akdeniz tahıl ticaretini kesmiştir.'),
  ('1066 yılında Manş Denizi\'ni yüzlerce taşıma gemisiyle geçerek İngiltere\'nin güney kıyılarına çıkarma yapan ve Pevensey\'de karaya çıkan Norman filosunun lideri kimdir?', 'Fatih William', ['Aslan Yürekli Richard', 'Yurtsuz John', 'Şarlman'], 'Normandiya Dükü William, Viking drakkarlarını andıran taşıma gemileriyle Manş\'ı aşmış ve bu deniz harekâtı ünlü Bayeux İşlemesi\'nde resmedilmiştir.'),
  ('Çin\'de nehir taşımacılığını deniz ticaretiyle bütünleştirmek amacıyla Sarı Nehir ile Yangtze Nehri havzalarını birbirine bağlayan ve Sui Hanedanı\'nda birleştirilen dev su yolu hangisidir?', 'Çin Büyük Kanalı', ['Kraliyet Fırat Kanalı', 'Karakum Su Kanalı', 'İndus Sulama Kanalı'], 'Pekin\'den Hangzhou\'ya yaklaşık 1.800 kilometre uzanan Büyük Kanal, güneyin pirinç rekoltesini kuzeydeki başkentlere güvenli iç su yoluyla taşımıştır.'),
  ('Hansa Birliği\'nin gayriresmî başkenti sayılan ve 12. yüzyılda Baltık kıyısında kurularak Kuzey Avrupa deniz ticaret hukukunun merkezine dönüşen Alman liman kenti hangisidir?', 'Lübeck', ['Münih', 'Frankfurt', 'Viyana'], 'Lübeck kenti, Hamburg ile kurduğu ortaklık üzerinden Hansa Birliği\'ne öncülük etmiş ve Baltık\'taki tuz-ringa balığı ticaretini yönetmiştir.'),
  ('İyon Ayaklanması\'nı bastırmak isteyen Pers İmparatorluğu\'nun MÖ 494\'te Miletos açıklarında 353 gemilik İyon donanmasını bozguna uğrattığı deniz savaşı hangisidir?', 'Lade Deniz Muharebesi', ['Kadeş Muharebesi', 'İssos Muharebesi', 'Granikos Muharebesi'], 'Fenike ve Mısır gemilerinden oluşan Pers donanması, Sisam gemilerinin saf değiştirmesiyle Lade Adası önünde İyon filosunu dağıtmıştır.'),
  ('Büyük İskender\'in MÖ 332\'de yedi ay süren kuşatma sonunda kıyıdan adaya taş ve toprak doldurarak mendirek (kıstak) inşa etmek suretiyle düşürdüğü ada kenti hangisidir?', 'Sur', ['Rodos', 'Kıbrıs Salamis', 'Girit Knossos'], 'Fenike\'nin en güçlü deniz üssü olan Sur Adası, İskender\'in inşa ettirdiği geçit ve Kıbrıs-Fenike gemilerinin ablukasıyla anakaraya bağlanarak alınmıştır.'),
  ('1298 yılında Dalmaçya kıyılarındaki Curzola (Korčula) Deniz Muharebesi\'nde Cenevizlilerin Venedik filosunu yendiği sırada esir düşüp hapishanede ünlü seyahatnamesini yazdıran Venedikli kimdir?', 'Marco Polo', ['İbn Battuta', 'Amerigo Vespucci', 'Niccolò de\' Conti'], 'Bir Venedik kadırgasına komuta ederken Curzola\'da Cenevizlilere esir düşen Marco Polo, Cenova hapishanesinde anılarını Rustichello da Pisa\'ya yazdırmıştır.'),
  ('Adriyatik\'in doğu kıyısında (bugünkü Dubrovnik) kurulan, Venedik\'in ticari rakibi olup 14. yüzyılda dünyada ilk kez gelen gemilere 40 günlük veba tecridi (karantina) uygulayan deniz cumhuriyeti hangisidir?', 'Ragusa Cumhuriyeti', ['Noli Cumhuriyeti', 'Gaeta Dükalığı', 'Sardinya Krallığı'], 'Ragusa (Dubrovnik) 1377\'de otuz günlük \'trentina\', ardından kırk günlük \'quarantina\' uygulamasıyla deniz yoluyla salgın yayılımını önlemeye çalışmıştır.'),
  ('Orta Çağ\'da Kuzey Denizi ve Baltık gemilerinde geminin yan tarafındaki \'sancak\' küreğinin yerini alarak 12. yüzyıldan itibaren kıç bodoslaması eksenine takılan yönlendirme donanımı nedir?', 'Menteşeli kıç dümeni', ['Üçgen flok yelkeni', 'Demir çıpa ırgatı', 'İskandil kurşunu'], 'Kıç bodoslamasına demir menteşelerle sabitlenen merkezi dümen, açık denizde büyük tonajlı gemilerin sert dalgalarda bile kolayca yönlendirilmesini sağlamıştır.'),
  ('Denizcilik terminolojisinde geminin sağ tarafına \'sancak\', sol tarafına \'iskele\' (İngilizcede starboard/port) denilmesinin tarihsel kökeni hangi yapısal özelliğe dayanır?', 'Eski gemilerde yönlendirme küreğinin sağ kıçta bulunması nedeniyle sol taraftan kıyıya yanaşılmasına', ['Kutup Yıldızı\'nın Akdeniz\'de doğuya giden gemilerin her zaman solunda kalmasına', 'Venedik tersanelerinde komutan sancağının yalnızca sol bordaya çekilmesine', 'Rüzgârların Kuzey Yarımküre\'de gemileri sürekli sağ tarafa yatırmasına'], 'Eski gemilerde dümen küreği sağ (steer-board) tarafta olduğu için küreğin kırılmaması amacıyla gemiler iskeleye her zaman sol bordalarından yanaşırdı.'),
  ('Orta Çağ İslam coğrafyasında Akdeniz\'e kıyısı olan sahil kalelerini ve Bizans donanmasının ani deniz baskınlarına karşı ateş-duman işaretiyle haberleşen kıyı gözetleme merkezlerini ifade eden kavram nedir?', 'Ribat', ['Bedesten', 'Kapan', 'İmarethane'], 'Kuzey Afrika ve Suriye kıyılarındaki ribatlar (örneğin Monastır ve Susa ribatları), denizden gelebilecek Bizans saldırılarına karşı savunma ve gözcülük işlevi görmüştür.'),
  ('10. yüzyılda Kuzey Afrika\'da Mehdiyyeli deniz üssünü inşa ettirerek Sicilya ve Güney İtalya kıyılarına seferler düzenleyen ve Akdeniz\'de güçlü bir Şii deniz gücü oluşturan hanedan hangisidir?', 'Fâtımîler', ['Gazneliler', 'Karahanlılar', 'Büveyhîler'], 'Tunus\'taki Mehdiyye müstahkem limanını kuran Fâtımîler, daha sonra Mısır\'ı da alarak Doğu Akdeniz ve Kızıldeniz ticaret yollarına hâkim olmuştur.'),
  ('Türkçede gemi bakım ve inşa yeri anlamında kullanılan \'tersane\' (İtalyanca arsenale) kelimesinin kökeni Orta Çağ İslam denizciliğindeki hangi kuruma dayanır?', 'Dârü\'s-sınâa', ['Beytü\'l-hikme', 'Dârü\'l-kurrâ', 'Dîvânü\'l-ceyş'], 'Arapça \'üretim/zanaat evi\' anlamına gelen Dârü\'s-sınâa, İtalyan deniz cumhuriyetlerine \'arsenale/darsena\', Osmanlı Türkçesine ise \'tersane\' olarak geçmiştir.'),
  ('Atina\'nın limanı Pire\'yi yaklaşık 6 kilometrelik paralel surlarla ana kente bağlayarak, kara ordusu kuşatma altındayken bile denizden tahıl ikmalinin sürmesini sağlayan devlet adamı kimdir?', 'Perikles', ['Solon', 'Kleisthenes', 'Peisistratos'], 'Uzun Surlar (Makrâ Teikhe) stratejisiyle Atina\'yı adeta bir adaya dönüştüren Perikles, Peloponez Savaşı\'nda kentin direncini deniz hâkimiyetine dayandırmıştır.'),
  ('Peloponez Savaşı sırasında MÖ 415-413 yıllarında Atina\'nın en görkemli donanmasını gönderip hem filosunu hem ordusunu tamamen kaybettiği felaketle sonuçlanan denizaşırı harekât hangisidir?', 'Sicilya Seferi', ['Midilli Kuşatması', 'Melos Çıkarması', 'Kıbrıs Harekâtı'], 'Alkibiades\'in teşvikiyle Siraküza\'ya karşı başlatılan Sicilya Seferi, Büyük Liman\'daki deniz yenilgisiyle Atina\'nın deniz imparatorluğunu çöküşe sürüklemiştir.'),
  ('1082 yılında Bizans İmparatoru I. Aleksios Komnenos\'un Norman deniz tehdidine karşı yardım alabilmek için İstanbul ve imparatorluk limanlarında gümrüksüz ticaret imtiyazı verdiği devlet hangisidir?', 'Venedik Cumhuriyeti', ['Aragon Krallığı', 'Portekiz Krallığı', 'Hansa Kentleri'], '1082 tarihli Altın Mühürlü Ferman (Khrysobullos), Venedik\'in Bizans deniz ticaretini ele geçirmesine ve imparatorluk gümrük gelirlerinin erimesine yol açmıştır.'),
  ('Kuzey Avrupa\'da 8. yüzyıl sonlarında Viking Çağı\'nın başlangıcı kabul edilen 793 yılındaki sürpriz deniz baskını İngiltere\'nin kuzeydoğusundaki hangi manastır adasını hedef almıştır?', 'Lindisfarne Adası', ['Wight Adası', 'Man Adası', 'Malta Adası'], 'Norveç\'ten gelen Viking gemilerinin 793\'te Kutsal Ada Lindisfarne Manastırı\'na yaptığı baskın, Orta Çağ Avrupa kıyılarında üç yüzyıl sürecek Viking akınlarını başlatmıştır.'),
  ('13. yüzyıl sonlarında Akdeniz\'de rüzgâr gülü çizgileri (kerte hatları) ve kıyı girintilerini yüksek doğrulukla göstererek Orta Çağ\'ın teolojik dünya haritalarından ayrılan denizci haritalarına ne denir?', 'Portolan haritası', ['Mappa Mundi', 'Kil tablet planı', 'Topografik izohips paftası'], 'Pusula yönleri ve liman mesafelerine göre ceylan derisi üzerine çizilen portolanlar (en eski örneği Pisane Haritası), uygulamalı Akdeniz denizciliğinin ürünüdür.'),
  ('Hint Okyanusu seyir kurallarını, muson mevsimlerini ve yıldız yüksekliklerini \'Kitâbü\'l-Fevâid fî Usûli\'l-Bahr ve\'l-Kavâid\' adlı eserinde toplayan 15. yüzyılın ünlü Arap deniz bilgini kimdir?', 'İbn Mâcid', ['İbn Haldun', 'İdrîsî', 'Birûnî'], '\'Denizlerin Aslanı\' lakaplı Şihâbüddin Ahmed İbn Mâcid, Kızıldeniz ve Hint Okyanusu\'ndaki Arap okyanus kılavuzluğunun zirve ismidir.'),
  ('1500 yılında Hindistan\'a gitmek üzere Portekiz\'den yola çıktığında alize rüzgârlarını yakalamak için Atlas Okyanusu\'nda geniş bir yay çizerken Brezilya kıyılarını keşfeden kaptan kimdir?', 'Pedro Álvares Cabral', ['Juan Ponce de León', 'Francisco Pizarro', 'Jacques Cartier'], 'Cabral\'ın \'Volta do mar\' (deniz dönüşü) rotasıyla ulaştığı Güney Amerika doğu kıyıları, Tordesillas hattının doğusunda kaldığından Portekiz sömürgesi olmuştur.'),
  ('1509 yılında Portekiz Valisi Francisco de Almeida\'nın Hindistan\'ın kuzeybatısında Memlûk, Gucerat ve Kalküta birleşik donanmasını yenerek Hint Okyanusu baharat yolunu Portekiz tekeline aldığı savaş hangisidir?', 'Diu Deniz Muharebesi', ['Preveze Deniz Muharebesi', 'Vadisseyl Muharebesi', 'Lepanto Deniz Muharebesi'], 'Diu Deniz Muharebesi, Portekiz okyanus topçuluğunun Hint Okyanusu\'ndaki geleneksel deniz güçlerine üstünlük kurduğu dönüm noktasıdır.'),
  ('1513 yılında Panama Kıstağı\'ndaki balta girmemiş ormanları aşarak Amerika kıtasının batısındaki Büyük Okyanus\'u gören ve buraya \'Güney Denizi\' adını veren İspanyol kâşif kimdir?', 'Vasco Núñez de Balboa', ['Hernando de Soto', 'Álvar Núñez Cabeza de Vaca', 'Francisco Vázquez de Coronado'], 'Balboa\'nın Panama sırtlarından Büyük Okyanus\'u görmesi, Amerika\'nın ötesinde devasa bir su kütlesi bulunduğunu kesinleştirerek Macellan\'ın seferine zemin hazırlamıştır.'),
  ('1519\'da İspanya\'dan beş gemiyle başlayıp Ferdinand Macellan\'ın Filipinler\'deki Mactan Adası\'nda ölümünün ardından 1522\'de tek gemiyle dünya çevresindeki ilk tam turu tamamlayan denizci kimdir?', 'Juan Sebastián Elcano', ['Antonio Pigafetta', 'Andrés de Urdaneta', 'Miguel López de Legazpi'], 'Macellan\'ın ölümünden sonra kalan \'Victoria\' gemisinin komutasını devralan Bask kökenli kaptan Elcano, 18 denizciyle İspanya\'ya dönmeyi başarmıştır.'),
  ('1497 yılında İngiltere Kralı VII. Henry adına Bristol Limanı\'ndan batıya yelken açarak Kuzey Amerika\'nın Newfoundland kıyılarına ulaşan ve İngiltere\'nin kıtadaki hak iddiasına temel oluşturan Venedik asıllı kaptan kimdir?', 'John Cabot', ['Martin Frobisher', 'Walter Raleigh', 'John Hawkins'], 'Cabot, Kuzey Atlantik üzerinden Asya\'ya kısa bir yol ararken Kuzey Amerika\'nın zengin morina balığı yataklarını ve doğu kıyılarını raporlamıştır.'),
  ('1534\'ten itibaren Fransa Kralı I. François adına Kuzey Amerika\'ya üç sefer düzenleyerek Saint Lawrence Körfezi ve nehrini keşfeden, Kanada adının haritalara girmesini sağlayan denizci kimdir?', 'Jacques Cartier', ['Samuel de Champlain', 'Robert Cavelier de La Salle', 'Louis Antoine de Bougainville'], 'Saint-Malo limanından yola çıkan Jacques Cartier, Stadacona ve Hochelaga (Montreal) yerli yerleşimlerine ulaşarak Yeni Fransa sömürgesinin temelini atmıştır.'),
  ('1595 yılında Hollanda adına Kuzeydoğu Geçidi üzerinden Asya\'ya gitmeye çalışırken gemisi Kuzey Kutbu buzullarında sıkışan ve Novaya Zemlya\'da kışı geçiren kâşif kimdir?', 'Willem Barentsz', ['Cornelis de Houtman', 'Jan Huygen van Linschoten', 'Piet Hein'], 'Spitsbergen (Svalbard) ve Ayı Adası\'nı keşfeden Barentsz\'in anısına İskandinavya ve Rusya kuzeyindeki deniz \'Barents Denizi\' olarak adlandırılmıştır.'),
  ('1602 yılında Amsterdam merkezli olarak kurulan, kendi savaş donanmasını besleme, kale inşa etme ve antlaşma yapma yetkisiyle tarihin ilk halka açık anonim deniz ticaret şirketi sayılan kurum hangisidir?', 'Hollanda Doğu Hindistan Şirketi', ['Hansa Deniz Tüccarları Loncası', 'Ceneviz Aziz George Bankası', 'Venedik Levant Kumpanyası'], 'Vereenigde Oostindische Compagnie (VOC), Cava\'daki Batavia\'yı merkez edinerek baharat ticaretinde Portekiz\'in yerini almıştır.'),
  ('Geminin su üzerindeki hızını ölçmek için ucuna üçgen ahşap levha bağlı ve üzerinde eşit aralıklarla düğümler bulunan ipin kum saati eşliğinde denize bırakılması düzeneğine ne denir?', 'Parakete', ['Usturlap', 'Sekstant', 'Filika'], 'Belirli sürede (genellikle 28 saniyelik kum saatinde) elden kayan düğüm (knot) sayısının sayılması, denizcilikteki hız birimi olan \'knot\' teriminin kaynağını oluşturmuştur.'),
  ('1642-1644 yıllarında Batavia\'dan yelken açarak Avustralya kıtasının güneyindeki adayı, Yeni Zelanda\'yı ve Fiji adalarını haritalandıran Hollandalı VOC kaptanı kimdir?', 'Abel Tasman', ['Willem Janszoon', 'Dirk Hartog', 'Jacob Roggeveen'], 'Avustralya\'yı hiç görmeden tüm kıtanın etrafını geniş bir çemberle dolaşan Tasman, Avustralya\'nın Güney Kutup kıtasına bağlı olmadığını kanıtlamıştır.'),
  ('Kuzey Amerika\'da hem Hollanda hem İngiltere adına Kuzeybatı Geçidi\'ni ararken New York\'taki nehri ve Kanada\'nın kuzeyindeki dev iç körfezi keşfeden, gemideki isyan sonucu filikayla terk edilen kaptan kimdir?', 'Henry Hudson', ['John Davis', 'William Baffin', 'Humphrey Gilbert'], '1611 yılında dondurucu sularda mürettebatının ayaklanmasıyla oğluyla birlikte küçük bir şalopada ölüme terk edilen Hudson, Kuzey Amerika haritasına adını bırakmıştır.'),
  ('Rus Çarı Deli Petro\'nun talimatıyla düzenlenen Kamçatka seferlerinde 1728 yılında Asya ile Kuzey Amerika kıtalarının karadan birleşmediğini aradaki boğazdan geçerek kanıtlayan Danimarka asıllı denizci kimdir?', 'Vitus Bering', ['Semyon Dejnyov', 'Fabian Gottlieb von Bellingshausen', 'İvan Krusenstern'], 'Rus donanmasında görev yapan Vitus Bering, Sibirya ile Alaska arasındaki boğazı ve Alaska kıyılarını haritalandırarak Kuzey Pasifik coğrafyasını aydınlatmıştır.'),
  ('Açık denizde enlem gök cisimlerinin yüksekliğiyle kolayca bulunabilirken \'boylamın\' (meridyenin) hassas biçimde hesaplanabilmesi tarihsel olarak hangi teknik sorunun çözülmesine bağlı kalmıştır?', 'Sallanan gemide referans limanının saatini şaşmadan koruyan hassas saatin yapılmasına', ['Manyetik kuzey kutbu ile coğrafi kuzey arasındaki sapma açısının sabitlenmesine', 'Derin okyanus tabanındaki akıntı hızlarının iskandil kurşunuyla ölçülmesine', 'Kutup Yıldızı\'nın Güney Yarımküre ufkundan görünmesini sağlayan teleskobun icadına'], 'Dünya saatte 15 derece döndüğünden, gemideki yerel öğle vakti ile Greenwich referans saati arasındaki her 4 dakikalık fark 1 derecelik boylama karşılık gelir.'),
  ('İngiliz Parlamentosu\'nun 1714 tarihli \'Boylam Yasası\' ile koyduğu büyük ödülü kazanmak üzere sarkaçsız yay dengeli deniz kronometresini (H4) geliştiren saat ustası kimdir?', 'John Harrison', ['Robert Hooke', 'Christiaan Huygens', 'Edmond Halley'], 'Marangoz kökenli kendi kendini yetiştirmiş bir usta olan John Harrison, nemden ve gemi yalpalamasından etkilenmeyen cep saati büyüklüğündeki H4 kronometresiyle boylam sorununu çözmüştür.'),
  ('1789 yılında Güney Pasifik\'teki Tahiti\'den Karayipler\'deki şeker kamışı tarlalarına \'ekmek ağacı\' fidanları taşırken Fletcher Christian önderliğindeki mürettebatın isyanıyla karşılaşan İngiliz gemisi hangisidir?', 'HMS Bounty', ['HMS Victory', 'HMS Beagle', 'HMS Erebus'], 'Bounty İsyanı sonrasında Kaptan William Bligh 18 sadık adamıyla açık bir filikada 6.500 kilometre yol kat ederek Timor\'a sağ salim ulaşmayı başarmıştır.'),
  ('1903-1906 yılları arasında \'Gjøa\' adlı küçük balıkçı gemisiyle Atlas Okyanusu\'ndan Büyük Okyanus\'a Kanada\'nın kuzeyindeki buzlu kanallardan gemiyle eksiksiz geçen ilk kâşif kimdir?', 'Roald Amundsen', ['Robert Peary', 'Vitus Bering', 'Richard Evelyn Byrd'], 'Norveçli kâşif Roald Amundsen, küçük ve sığ su çekimli Gjøa teknesiyle yüzyıllardır aranan Kuzeybatı Geçidi\'ni baştan sona denizden geçen ilk insan olmuştur.'),
  ('1872-1876 yılları arasında okyanus tabanı derinliklerini, su sıcaklıklarını ve binlerce yeni deniz canlısını inceleyerek modern \'oşinografi\' (okyanus bilimi) disiplininin kuruluşunu başlatan İngiliz seferi hangisidir?', 'Challenger Seferi', ['Discovery Seferi', 'Meteor Seferi', 'Belgica Seferi'], 'Topları sökülerek yüzer laboratuvara dönüştürülen HMS Challenger korveti, Mariana Çukuru\'nun ilk derinlik ölçümünü ve Orta Atlantik Sırtı tespitini gerçekleştirmiştir.'),
  ('19. yüzyıl ortalarında Çin\'den Londra ve New York\'a taze çay, Avustralya\'dan yün ve altın taşımak üzere inşa edilen, keskin pruvalı ve çok yelkenli en hızlı ticaret gemisi sınıfı hangisidir?', 'Kliper', ['Şebek', 'Kadırga', 'Karaka'], '\'Cutty Sark\' ve \'Flying Cloud\' gibi ünlü örnekleriyle tanınan kliper gemileri, buharlı gemilerin erken döneminde hız rekorlarını ellerinde tutmuştur.'),
  ('Yelkenli ahşap gemilerin su altındaki gövde tahtalarını sıcak denizlerde hızla kemirerek delik deşik eden \'Teredo navalis\' (gemi kurdu) yumuşakçasına karşı 18. yüzyıl sonlarında geliştirilen koruma yöntemi nedir?', 'Karinanın bakır levhalarla kaplanması', ['Güvertenin zeytinyağı ile yıkanması', 'Omurgaya mıknatıslı demir çubuk çakılması', 'Ambarlara kireç taşı blokları dizilmesi'], 'İngiliz donanmasının yaygınlaştırdığı bakır kaplama, hem gemi kurdunu engellemiş hem de yosun-midye tutunmasını azaltarak gemi hızını belirgin ölçüde artırmıştır.'),
  ('Atlas Okyanusu\'nun ortasında alize rüzgârlarının kesildiği, Ekvator çevresindeki alçak basınç kuşağında yelkenli gemilerin haftalarca hareketsiz mahsur kalabildiği durgun deniz bölgesi nasıl adlandırılır?', 'Doldrums', ['Kükreyen Kırklar fırtına kuşağı', 'Golfstrim sıcak su akıntısı', 'Labrador buzdağı koridoru'], 'Ekvatoral durgunluk kuşağı (Doldrums) ve subtropikal At Enlemleri, yelken çağında içme suyu tükenen gemiler için en tehlikeli meteorolojik engellerdendi.'),
  ('1628 yılında İsveç Kralı II. Gustav Adolf\'un emriyle inşa edilen, ancak ağır bronz toplarının yarattığı ağırlık merkezi hatası yüzünden ilk yolculuğunda Stockholm Limanı\'ndan çıkarken rüzgârla alabora olan ünlü kalyon hangisidir?', 'Vasa', ['Sovereign of the Seas', 'Santísima Trinidad', 'Soleil Royal'], 'Baltık Denizi\'nin az tuzlu ve soğuk sularında gemi kurdu yaşamadığı için Vasa kalyonu 333 yıl sonra 1961\'de neredeyse bütün halinde su yüzüne çıkarılmıştır.'),
  ('1806 yılında rüzgâr şiddetini karadaki ağaçlara değil, tam donanımlı bir yelkenli savaş fırkateyninin açabileceği yelken miktarına göre 0\'dan 12\'ye kadar sınıflandıran İrlanda asıllı İngiliz amiral kimdir?', 'Francis Beaufort', ['Samuel Plimsoll', 'Matthew Fontaine Maury', 'FitzRoy'], 'Beaufort Rüzgâr Ölçeği (0: Sakin, 12: Kasırga), gemi seyir jurnallerinde öznel rüzgâr ifadeleri yerine standart bilimsel kayıt tutulmasını sağlamıştır.'),
  ('Ticaret gemilerinin aşırı yüklenerek fırtınalarda batmasını ve sigorta yolsuzluklarını önlemek amacıyla 1876\'da İngiltere\'de gemi bordalarına azami su kesimi çizgisi (\'yükleme sınırı işareti\') konulmasını sağlayan parlamenter kimdir?', 'Samuel Plimsoll', ['Isambard Kingdom Brunel', 'Edward John Smith', 'Samuel Cunard'], 'Gemi bordalarındaki daire ve yatay çizgilerden oluşan \'Plimsoll işareti\', suyun tuzluluk ve sıcaklığına göre güvenli yükleme sınırını gösteren uluslararası standart olmuştur.'),
  ('19. yüzyılın ortalarında transatlantik taşımacılıkta \'Great Western\', \'Great Britain\' (ilk demir gövdeli uskurlu okyanus gemisi) ve dev \'Great Eastern\' gemilerini tasarlayan İngiliz mühendis kimdir?', 'Isambard Kingdom Brunel', ['Thomas Andrews', 'Ferdinand de Lesseps', 'Gustave Eiffel'], 'Brunel\'in 1858\'de suya indirilen dev gemisi SS Great Eastern, daha sonra Avrupa ile Kuzey Amerika arasındaki ilk kalıcı denizaltı telgraf kablosunu döşemiştir.'),
  ('1912 yılı Nisan ayında Southampton\'dan New York\'a yaptığı ilk seferinde Kuzey Atlantik\'te buzdağına çarparak batan RMS Titanic faciasının ardından denizde can güvenliği için kabul edilen uluslararası sözleşme hangisidir?', 'SOLAS (Denizde Can Emniyeti Uluslararası Sözleşmesi)', ['MARPOL (Gemilerden Kaynaklanan Kirliliğin Önlenmesi Sözleşmesi)', 'Montrö Boğazlar Sözleşmesi', 'Cenevre Açık Deniz Balıkçılık Protokolü'], '1914\'te ilk versiyonu kabul edilen SOLAS ile tüm yolculara yetecek sayıda can filikası bulundurulması, 24 saat kesintisiz telsiz nöbeti ve Uluslararası Buz Devriyesi zorunlu kılınmıştır.'),
  ('1890\'da yayımladığı \'Tarih Üzerinde Deniz Gücünün Etkisi\' adlı eseriyle okyanus yollarını kontrol eden açık deniz muharebe donanmalarının büyük devlet olmanın anahtarı olduğunu savunan stratejist kimdir?', 'Alfred Thayer Mahan', ['Carl von Clausewitz', 'Halford Mackinder', 'Giulio Douhet'], 'ABD\'li Amiral Mahan\'ın deniz hâkimiyeti teorisi, 20. yüzyıl başında İngiltere, Almanya, ABD ve Japonya arasındaki zırhlı donanma yarışına doğrudan yön vermiştir.'),
  ('Avustralya anakarası ile Tazmanya Adası arasında yer alan ve 1798\'de George Bass ile Matthew Flinders tarafından geçiş yapılabilir bir boğaz olduğu kanıtlanan su yolu hangisidir?', 'Bass Boğazı', ['Torres Boğazı', 'Cook Boğazı', 'Sunda Boğazı'], 'Bass Boğazı\'nın keşfi, Avrupa\'dan Sidney\'e giden yelkenli gemilerin Tazmanya\'nın güneyini dolaşmasına gerek bırakmayarak yolu yaklaşık 700 deniz mili kısaltmıştır.'),
  ('1914-1916 İmparatorluk Trans-Antarktika Seferi\'nde \'Endurance\' gemisi Weddell Denizi buzlarında ezilip battıktan sonra açık bir filikayla Güney Georgia Adası\'na ulaşıp tüm ekibini sağ kurtaran lider kimdir?', 'Ernest Shackleton', ['Douglas Mawson', 'Edmund Hillary', 'Vivian Fuchs'], 'Shackleton ve beş arkadaşının \'James Caird\' adlı küçük filikayla fırtınalı Güney Okyanusu\'nda 1.300 km yol alması denizcilik tarihinin en büyük açık tekne seyirlerindendir.'),
  ('1947 yılında Güney Amerika yerlilerinin antik dönemde okyanus akıntılarıyla Polinezya adalarına ulaşabileceğini kanıtlamak için Peru\'dan \'Kon-Tiki\' adlı balsa ağacı salla Pasifik\'i geçen araştırmacı kimdir?', 'Thor Heyerdahl', ['Jacques-Yves Cousteau', 'Auguste Piccard', 'Tim Severin'], 'Norveçli etnograf Thor Heyerdahl, Humboldt akıntısı ve rüzgârlarla sürüklenen Kon-Tiki salıyla 101 günde Tuamotu Takımadaları\'na ulaşarak deneysel deniz arkeolojisine öncülük etmiştir.'),
  ('1609 yılında yayımladığı \'Mare Liberum\' (Açık Deniz / Serbest Deniz) adlı eseriyle okyanusların hiçbir devletin mülkiyetine alınamayacağını ve tüm ulusların seyrüseferine açık olduğunu savunan hukukçu kimdir?', 'Hugo Grotius', ['John Selden', 'Niccolò Machiavelli', 'Jean Bodin'], 'Hollandalı hukukçu Grotius, Portekiz ve İspanya\'nın okyanusları paylaşma iddiasına karşı çıkarak modern uluslararası deniz hukukunun \'açık denizlerin serbestliği\' ilkesini kurmuştur.'),
  ('18. yüzyılda bir kıyı devletinin karasuları genişliğinin \'3 deniz mili\' olarak kabul edilmesini temellendiren ve Hollandalı hukukçu Cornelius van Bynkershoek tarafından formüle edilen kural neye dayanıyordu?', 'Kıyıdaki bataryalardan ateşlenen bir top mermisinin ulaşabildiği azami menzile', ['Kıyıdaki deniz feneri ışığının açık havada seçilebildiği ufuk mesafesine', 'Kürekli bir sahil güvenlik filikasının bir saatte gidebildiği mesafeye', 'Gelgit çekilmesi sırasında deniz tabanının sığlaştığı kıta sahanlığına'], '\'Kara hâkimiyeti silahların gücünün bittiği yerde biter\' ilkesinden doğan \'top atımı kuralı\' (yaklaşık 3 deniz mili), 20. yüzyıla dek karasuları sınırının ölçütü olmuştur.'),
  ('1651 yılında Oliver Cromwell yönetimindeki İngiltere\'nin Hollanda taşımacılık tekelini kırmak için çıkardığı, İngiltere ve sömürgelerine gelen malların yalnızca İngiliz veya malın menşe ülkesinin gemileriyle taşınmasını şart koşan yasa nedir?', 'Seyrüsefer Yasaları (Navigation Acts)', ['Tahıl Yasaları (Corn Laws)', 'Çitleme Kararnameleri', 'Damga Vergisi Kanunu'], 'Merkantilist denizcilik politikasının en sert örneği olan Seyrüsefer Yasaları, 17. yüzyıldaki İngiliz-Hollanda Deniz Savaşları\'nın doğrudan çıkış nedeni olmuştur.'),
  ('1620 yılında İngiltere\'nin Plymouth limanından ayrılarak dinî özgürlük arayışıyla Kuzey Amerika\'daki Massachusetts kıyılarına ulaşan \'Pilgrim Babaları\'nı taşıyan ve güvertesinde öz yönetim sözleşmesi imzalanan gemi hangisidir?', 'Mayflower', ['Susan Constant', 'Half Moon', 'Constitución'], 'Karaya çıkmadan önce gemi kamarasında imzalanan \'Mayflower Sözleşmesi\', Amerikan kolonilerindeki demokratik öz yönetim belgelerinin öncülerinden kabul edilir.'),
  ('Devletlerin savaş zamanında özel şahıslara ait silahlı gemilere (\'privateer\') düşman ticaret gemilerini zapt etme yetkisi tanıdığı resmî izin belgesi denizcilik tarihinde nasıl adlandırılırdı?', 'Korsanlık beratı', ['Konşimento senedi', 'Karantina pratika belgesi', 'Navlun poliçesi'], 'Yasadışı deniz haydutlarından (pirate) farklı olarak devlet beratı taşıyan privateer kaptanlar (örneğin Surcouf veya erken dönem Drake), ganimetin bir payını hükümdara verirdi.'),
  ('Karayipler\'deki \'Korsanlığın Altın Çağı\'nda \'Queen Anne\'s Revenge\' adlı 40 toplu gemisiyle Kuzey Amerika kıyılarını ablukaya alan ve \'Karasakal\' (Blackbeard) lakabıyla tanınan İngiliz korsan kimdir?', 'Edward Teach', ['Henry Morgan', 'William Kidd', 'Bartholomew Roberts'], 'Eski bir Fransız köle gemisi olan La Concorde\'u ele geçirip Queen Anne\'s Revenge adını veren Edward Teach, 1718\'de Ocracoke Koyu\'nda Kraliyet Donanması\'yla girdiği çatışmada öldürülmüştür.'),
  ('19. yüzyıl başlarında Güney Çin Denizi\'nde yüzlerce cunk gemisi ve on binlerce denizciden oluşan \'Kırmızı Bayrak Filosu\'nu yöneterek Çin ve Avrupa donanmalarına meydan okuyan kadın korsan lider kimdir?', 'Ching Shih', ['Anne Bonny', 'Mary Read', 'Grace O\'Malley'], 'Eşinin ölümünden sonra dev korsan konfederasyonunu katı disiplin yasalarıyla yöneten Ching Shih, 1810\'da Qing İmparatorluğu\'ndan genel af ve servetini koruma hakkı kopararak emekli olmuştur.'),
  ('1956 yılında Newark Limanı\'ndan Houston\'a yaptığı seferle standartlaştırılmış çelik yük kasalarının vinçle doğrudan gemiden kamyona aktarılmasını başlatan ve küresel deniz ticaretinde \'konteyner devrimi\'ni yaratan girişimci kimdir?', 'Malcom McLean', ['Aristotle Onassis', 'Henry Kaiser', 'Cornelius Vanderbilt'], 'Kamyon taşımacılığından gelen Malcom McLean, II. Dünya Savaşı tankeri \'Ideal X\' üzerinde taşıdığı standart konteynerlerle liman yükleme sürelerini haftalardan saatlere indirmiştir.'),
  ('1090 yılında Çaka Bey komutasındaki Türk filosu ile Konstantinos Dalassenos komutasındaki Bizans donanması arasında Sakız Adası yakınlarında gerçekleşen ilk büyük Türk deniz savaşı hangisidir?', 'Koyun Adaları Deniz Muharebesi', ['Bafeus Muharebesi', 'Miryokefalon Savaşı', 'Pasinler Muharebesi'], 'Çaka Bey Koyun Adaları (Oinousses) önünde gemilerini zincirlerle birbirine bağlayarak yaptığı savunma ve hücumla Bizans donanmasına ağır kayıplar verdirmiştir.'),
  ('Anadolu Selçuklu Devleti döneminde Kastamonu uç beyi Hüsameddin Çoban Bey\'in Sinop Tersanesi\'nden kalkan donanmayla Karadeniz\'i aşarak Kırım\'da ele geçirdiği ticaret limanı hangisidir?', 'Sudak', ['Odesa', 'Azak', 'Sivastopol'], 'I. Alaeddin Keykubad devrinde düzenlenen Sudak Seferi, Anadolu Selçuklularının gerçekleştirdiği ilk ve en kapsamlı denizaşırı askeri harekâttır.'),
  ('14. yüzyılın ilk yarısında İzmir\'i Haçlılardan geri alan, \'Gazi\' adlı kadırgasıyla Ege ve Balkan kıyılarına 20\'den fazla deniz seferi düzenleyen Aydınoğulları hükümdarı kimdir?', 'Umur Bey', ['İlyas Bey', 'İsa Bey', 'Hızırşah Bey'], 'Enverî\'nin \'Düstûrnâme\' adlı eserinde kahramanlıkları destanlaştırılan Aydınoğlu Gazi Umur Bey, 1348\'de İzmir Limanı kalesi önünde şehit düşmüştür.'),
  ('Çelebi Mehmed döneminde 1416 yılında Venedik Amiral Pietro Loredan komutasındaki donanmaya karşı Gelibolu önlerinde çarpışarak şehit düşen Osmanlı derya beyi kimdir?', 'Çalı Bey', ['Baltaoğlu Süleyman Bey', 'Kemal Reis', 'Burak Reis'], '1416 Çalı Bey Deniz Muharebesi, genç Osmanlı donanmasının dönemin en güçlü deniz devleti Venedik ile giriştiği ilk açık deniz sınavıdır.'),
  ('1453 İstanbul Kuşatması sırasında Haliç ağzındaki zinciri zorlayan, ancak Ceneviz gemilerinin rüzgâr üstünlüğüyle ablukayı yarması üzerine Fatih Sultan Mehmed tarafından görevden alınan donanma komutanı kimdir?', 'Baltaoğlu Süleyman Bey', ['Zağanos Paşa', 'Karaca Paşa', 'Çandarlı Halil Paşa'], '20 Nisan 1453\'te yüksek bordalı dört Hristiyan gemisinin Haliç\'e girmesini engelleyemeyen Baltaoğlu Süleyman Bey\'in yerine Hamza Bey getirilmiştir.'),
  ('1499 yılındaki Sapienza (Modon/Bradano Adası) Deniz Muharebesi\'nde iki Venedik kalyonuna bordalayıp barut ve reçineyle onları kendi gemisiyle birlikte ateşe vererek şehit düşen Osmanlı reisi kimdir?', 'Burak Reis', ['Aydın Reis', 'Kurdoğlu Muslihiddin Reis', 'Şaban Reis'], 'Burak Reis\'in komuta ettiği dev \'göke\' ile iki Venedik gemisini yakarak batırması Venedik donanmasının düzenini bozmuş, ada denizciler arasında \'Burak Reis Adası\' olarak anılmıştır.'),
  ('Barbaros\'un 1546\'da vefatından sonra Akdeniz\'de \'Barbaros\'un kılıcı\' olarak anılan, Cerbe Adası\'nda Andrea Doria\'nın kapattığı sığ koydan gemilerini yağlı kızaklarla karadan aşırarak kurtulan büyük denizci kimdir?', 'Turgut Reis', ['Piyale Paşa', 'Cağaloğlu Sinan Paşa', 'Kılıç Ali Paşa'], '1551\'de Trablusgarp\'ı fethederek beylerbeyi olan Turgut Reis, yüksek manevra dehasıyla Batı kaynaklarında \'Dragut\' adıyla efsaneleşmiştir.'),
  ('1565 yılındaki Büyük Malta Kuşatması sırasında Saint Elmo Kalesi önlerinde başından şarapnel parçasıyla vurularak 80 yaşında şehit düşen ve Trablusgarp\'a defnedilen Osmanlı denizcisi kimdir?', 'Turgut Reis', ['Kemal Reis', 'Oruç Reis', 'Pîrî Reis'], 'Kuşatmaya sonradan filosuyla katılan Turgut Reis\'in şehadeti, Saint Jean Şövalyeleri\'ne karşı yürütülen Malta Kuşatması\'nın başarısızla sonuçlanmasında önemli etken olmuştur.'),
  ('Osmanlıların dört Hint Deniz Seferi\'nde Portekizlileri Hint Okyanusu\'ndan tamamen çıkaramamasının gemi teknolojisi açısından en temel nedeni aşağıdakilerden hangisidir?', 'Akdeniz için tasarlanan kürekli Osmanlı kadırgalarının okyanus dalgalarına dayanıksız kalması', ['Osmanlı donanmasında barutlu top ve arkebüz tüfeklerinin henüz hiç kullanılmaması', 'Portekiz donanmasının kömürle çalışan çelik zırhlı buharlı gemilerden oluşması', 'Süveyş Kıstağı\'nın o tarihte kanalla açık olması yüzünden Portekiz gemilerinin Akdeniz\'e girmesi'], 'Alçak bordalı çektiri/kadırga sınıfı gemiler Kızıldeniz ve Akdeniz\'in iç sularına uygunken, yüksek bordalı Portekiz kalyonları ve karakaları okyanus musonlarına çok daha elverişliydi.'),
  ('1552\'deki ikinci Hint Deniz Seferi\'nde Maskat\'ı alıp Hürmüz Kalesi\'ni kuşatan, ancak Basra\'da donanmanın çoğunu bırakıp yalnızca üç kadırgayla Süveyş\'e dönmesi yüzünden 1553\'te Kahire\'de idam edilen denizci kimdir?', 'Pîrî Reis', ['Hadım Süleyman Paşa', 'Seydi Ali Reis', 'Selman Reis'], 'Hint Kaptanlığı görevindeyken Basra Beylerbeyi Kubad Paşa\'nın olumsuz raporları ve donanmayı Basra\'da terk ettiği suçlamasıyla seksenli yaşlarındaki Pîrî Reis idam edilmiştir.'),
  ('1554\'te Basra\'daki Osmanlı kadırgalarını Süveyş\'e götürürken Portekiz pusuları ve \'Fil Tufanı\' fırtınasıyla Hindistan\'ın Gucerat kıyılarına sürüklenen, oradan karayoluyla 3,5 yılda İstanbul\'a dönen kaptan kimdir?', 'Seydi Ali Reis', ['Salih Reis', 'Aydın Reis', 'Kurdoğlu Hızır Reis'], 'Seydi Ali Reis, Hindistan, Sind, Afganistan, Mâverâünnehir ve İran üzerinden Edirne\'deki Kanuni\'nin huzuruna ulaşarak destansı yolculuğunu kaleme almıştır.'),
  ('1560\'lı yıllarda Güneydoğu Asya\'daki Sumatra Adası\'nda Portekiz saldırılarına karşı Osmanlı Padişahı Kanuni ve II. Selim\'den topçu ve donanma yardımı isteyen, Kurdoğlu Hızır Reis\'in yardıma gönderildiği Müslüman devlet hangisidir?', 'Açe Sultanlığı', ['Malakka Sultanlığı', 'Brunei Sultanlığı', 'Bengal Sultanlığı'], 'Açe Sultanı Alaeddin\'in elçileri İstanbul\'a gelerek bağlılık bildirmiş; Yemen isyanı ana filoyu alıkoysa da iki gemiyle gönderilen Osmanlı top ustaları ve denizcileri Açe\'ye ulaşmıştır.'),
  ('Kılıç Ali Paşa\'nın 1574 yılında Sinan Paşa ile birlikte İspanyol işgalinden ve Hafsî hanedanından kesin olarak kurtararak Osmanlı eyaletine dönüştürdüğü Kuzey Afrika ülkesi hangisidir?', 'Tunus', ['Mısır', 'Habeşistan', 'Sudan'], 'Halkulvad (La Goulette) Kalesi ve Tunus\'un 1574\'te alınmasıyla İnebahtı sonrasında Osmanlı donanmasının Akdeniz\'deki caydırıcılığı yeniden kanıtlanmıştır.'),
  ('1645 yılında başlayıp 24 yıl süren Girit (Kandiye) Kuşatması, Osmanlı denizcilik teknolojisinde hangi köklü yapısal dönüşümün zorunlu olduğunu açıkça göstermiştir?', 'Kürekli kadırgadan rüzgârla çalışan yüksek ateş güçlü yelkenli kalyona geçişi', ['Ahşap kalyonlardan dizel motorlu sualtı hücum botlarına geçişi', 'Akdeniz tersanelerinin kapatılıp tüm gemilerin Hint Okyanusu\'nda üretilmesini', 'Donanmada top kullanımının bırakılıp yalnızca Rum ateşi sifonlarına dönülmesini'], 'Venediklilerin Çanakkale Boğazı\'nı yüksek bordalı kalyonlarla ablukaya alması, Osmanlı bahriyesinin kadırga geleneğini bırakıp kalyon inşasına yönelmesini hızlandırmıştır.'),
  ('Girit Seferi sırasında Venedik donanmasının Çanakkale Boğazı ağzında yarattığı deniz ablukası krizini ve Osmanlı bahriyesinin ıslahı için alınması gereken önlemleri 1656\'da \'Tuhfetü\'l-Kibâr fî Esfâri\'l-Bihâr\' eseriyle yazan bilgin kimdir?', 'Kâtip Çelebi', ['Naima Efendi', 'Koçi Bey', 'Peçevi İbrahim Efendi'], 'Kâtip Çelebi bu eserinde kuruluşundan kendi dönemine dek Osmanlı deniz seferlerini özetlemiş ve deniz kaptanlarına yönelik 40 maddelik stratejik öğütler sıralamıştır.'),
  ('1695 yılında Koyun Adaları Deniz Muharebesi\'nde Venedik filosunu yenerek Sakız Adası\'nı düşman işgalinden kurtaran ve 1701 tarihli \'Bahriye Kanunnamesi\' ile Osmanlı\'da kalıcı kalyon dönemini başlatan Kaptan-ı Derya kimdir?', 'Mezomorto Hüseyin Paşa', ['Merzifonlu Kara Mustafa Paşa', 'Baltacı Mehmet Paşa', 'Nevşehirli Damat İbrahim Paşa'], 'Cezayir ocaklarında kalyon savaşlarında pişen Mezomorto (yarı ölü anlamında İtalyanca lakaplı) Hüseyin Paşa, Osmanlı donanmasını yelkenli hat gemisi düzenine geçirmiştir.'),
  ('Kanuni Sultan Süleyman\'ın Rodos\'un 1522\'de fethi sırasında Saint Jean Şövalyeleri\'nin adayı tahliye etmesine izin vermesinin uzun vadede Osmanlı deniz ticaretinde yarattığı stratejik sorun ne olmuştur?', 'Şövalyelerin Şarlken\'in tahsis ettiği Malta Adası\'na yerleşerek Akdeniz\'de korsanlığı sürdürmesi', ['Şövalyelerin Süveyş Kıstağı\'nı işgal ederek Hint baharat yolunu tamamen kapatması', 'Şövalyelerin Karadeniz\'deki Kefe ve Trabzon kalelerini ele geçirip Tuna\'yı kesmesi', 'Şövalyelerin İngiltere ile birleşip Cebelitarık\'ta demir zincir çekmesi'], '1530\'da İmparator V. Karl (Şarlken) tarafından kendilerine verilen Malta ve Trablusgarp\'a yerleşen şövalyeler, yüzyıllarca Doğu-Batı Akdeniz boğazında Osmanlı ticaret gemilerine saldırmıştır.'),
  ('II. Bayezid devrinde 1484 yılında düzenlenen seferle Tuna ve Dinyester nehirlerinin Karadeniz\'e döküldüğü ağızlarda ele geçirilerek Kırım ile kara bağlantısını kuran ve Karadeniz\'i tamamen kapatan iki kale hangileridir?', 'Kili ve Akkerman', ['Belgrad ve Böğürdelen', 'Modon ve Koron', 'Rodos ve İstanköy'], 'Boğdan\'ın elindeki Kili ve Akkerman liman kalelerinin fethiyle Karadeniz kıyılarındaki son yabancı ticaret kapıları da Osmanlı denetimine girmiştir.'),
  ('Mimar Sinan\'ın Tophane sahilinde Kılıç Ali Paşa için inşa ettiği külliyenin vakıf efsanesine göre paşanın \'Ben derya adamıyım, camimi derya üzerine kurarım\' diyerek seçtiği zemin nasıl oluşturulmuştur?', 'Tophane kıyısında denizin taş ve toprakla doldurulmasıyla kazanılan alan üzerine', ['Kız Kulesi kayalığının yanına demir kazıklar çakılmasıyla kurulan iskele üzerine', 'Haliç\'in ortasında birbirine zincirlenmiş eski kalyon gövdeleri üzerine', 'Sarayburnu surlarının dışındaki Bizans fener kulesinin temelleri üzerine'], '1580 yılında tamamlanan Tophane Kılıç Ali Paşa Külliyesi, kıyı dolgusuyla deniz kenarında yükselen ve Ayasofya plan şemasını yorumlayan seçkin bir denizci vakfıdır.'),
  ('1538 yılında Hadım Süleyman Paşa\'nın Süveyş Tersanesi\'nde inşa edilen 70\'ten fazla gemiyle çıktığı ilk Hint Deniz Seferi\'nde Osmanlı idaresine bağladığı Kızıldeniz girişindeki stratejik ülke neresidir?', 'Aden ve Yemen sahilleri', ['Zenzibar ve Mozambik adaları', 'Seylan ve Maldiv takımadaları', 'Kalküta ve Goa limanları'], 'Hadım Süleyman Paşa Hindistan\'daki Diu Kalesi\'ni Gucerat\'ın destek çekmesi nedeniyle alamasa da dönüşte Aden ve Zebîd\'i zaptederek Babülmendep girişini güvenceye almıştır.'),
  ('Osmanlı donanmasında üç direkli ve güverteleri boyunca çift veya üç sıra top dizili en büyük yelkenli savaş gemilerine 18. yüzyılda verilen ad aşağıdakilerden hangisidir?', 'Üç ambarlı kalyon', ['Kancabaş çektiri', 'Kırlangıç kayığı', 'At gemisi'], 'Yaklaşık 110-120 top taşıyan ve 1.000\'den fazla mürettebat barındıran \'Mahmudiye\' veya \'Mesudiye\' öncesi dönemin \'Selimiye\' gibi üç ambarlıları, Osmanlı yelkenli filosunun zirvesiydi.'),
  ('Sultan II. Mahmud döneminde 1829 yılında Tersâne-i Âmire başmimarı Mehmet Efendi ve Mehmet Kalfa tarafından tamamen yerli işçilikle inşa edilen, 128 top kapasiteli dünyanın en büyük ahşap savaş kalyonlarından biri hangisidir?', 'Mahmudiye Kalyonu', ['Savarona Yatı', 'Yavuz Muharebe Kruvazörü', 'Bandırma Vapuru'], 'Yıllarca Osmanlı donanmasının sancak gemisi olan ve Kırım Savaşı\'nda Sivastopol bombardımanına da katılan Mahmudiye Kalyonu, Türk ahşap gemi inşaatının şaheseridir.'),
  ('1886 yılında Osmanlı Tersâne-i Âmire kızaklarında monte edilerek Haliç sularına indirilen, İsveçli mühendis Nordenfelt tasarımı \'Abdülhamid\' denizaltısının dünya deniz harp tarihindeki ayrıcalığı nedir?', 'Su altındayken baş kısmından torpido ateşlemeyi başaran tarihteki ilk denizaltı olması', ['Nükleer reaktör gücüyle Kuzey Kutbu buzullarının altından geçen ilk denizaltı olması', 'Atlantik Okyanusu\'nu hiç yüzeye çıkmadan şnorkelle geçen ilk gemi olması', 'Sonar dalgalarıyla sualtı mayınlarını otomatik imha eden ilk araç olması'], 'Yunanistan\'ın denizaltı alması üzerine II. Abdülhamid\'in girişimiyle Taşkızak Tersanesi\'nde birleştirilen Abdülhamid (Nordenfelt II), 1888\'de Sarayburnu akıntısında su altından torpido atışı gerçekleştirmiştir.'),
  ('13. yüzyıl sonlarında Batı Anadolu\'da Rodos\'un bir kısmına ve Güneybatı Anadolu kıyılarına hâkim olarak Beçin ve Balat üzerinden Venedik ile deniz ticaret antlaşmaları yapan Türkmen beyliği hangisidir?', 'Menteşeoğulları Beyliği', ['Eretna Beyliği', 'Germiyanoğulları Beyliği', 'Ramazanoğulları Beyliği'], 'Muğla, Milas, Beçin ve Finike sahillerinde güçlü bir deniz filosu kuran Menteşeoğulları, Batı Anadolu\'da deniz gazası geleneğini başlatan öncü beyliklerdendir.'),
  ('Osmanlı donanmasında Kaptan-ı Derya\'ya bağlı sancakların (\'Cezâyir-i Bahr-i Sefîd\' - Akdeniz Adaları Eyaleti) başında bulunan ve savaş zamanı sancak gelirlerine göre kendi kadırgalarıyla donanmaya katılan yöneticilere ne denirdi?', 'Derya Beyi', ['Kubbealtı Veziri', 'Kazasker', 'Defterdar'], 'Rodos, Midilli, Sakız, Eğriboz, İnebahtı gibi deniz sancaklarını yöneten Derya Beyleri, tımar sisteminin denizdeki karşılığı olarak donanmaya hazır kadırgalarla katılırdı.'),
  ('Sultan Abdülaziz döneminde donanmaya yapılan büyük yatırımlarla İngiltere ve Fransa tersanelerinden sipariş edilen zırhlı fırkateyn ve korvetlerle Osmanlı bahriyesi dünya sıralamasında hangi konuma yükselmiştir?', 'Dünyanın üçüncü büyük zırhlı donanması konumuna', ['Buharlı gemi kullanmayan son yelkenli donanma konumuna', 'Yalnızca nehir kanonbotlarından oluşan kıyı gücü konumuna', 'Uçak gemisi filosuna sahip ilk Akdeniz gücü konumuna'], 'Abdülaziz devrinde dış borçlanmanın da etkisiyle \'Aziziye\', \'Orhaniye\', \'Mahmudiye\', \'Osmaniye\' ve \'Mesudiye\' gibi zırhlılar alınarak gemi sayısı bakımından İngiltere ve Fransa\'nın ardından üçüncülüğe ulaşılmıştır.'),
  ('1909 yılında halkın bağışlarıyla Osmanlı donanmasını modernize etmek, yeni dretnot ve muhripler satın almak amacıyla kurulan ve madalyalar bastırıp kampanyalar yürüten sivil toplum kuruluşu hangisidir?', 'Donanma-yı Osmânî Muâvenet-i Milliye Cemiyeti', ['Hilâl-i Ahmer Cemiyeti', 'Darülaceze Vakfı', 'Cemiyet-i İlmiye-i Osmaniye'], 'Halkın alyanslarından harçlıklarına kadar bağış topladığı Donanma Cemiyeti, Almanya\'dan alınan \'Yadigâr-ı Millet\' ve \'Muâvenet-i Milliye\' gibi muhriplerin finansmanını sağlamıştır.'),
  ('1588 Gravelines Deniz Muharebesi\'nde İngiliz donanmasının İspanyol Armadası\'nın bordalama taktiğini boşa çıkarmasını sağlayan temel topçuluk ve gemi tasarımı üstünlüğü neydi?', 'Daha alçak ve hızlı kalyonlarla uzaktan seri top atışı yapabilmeleri', ['Buhar gücüyle rüzgârın tersi yönde zırhlı mahmuz hücumu gerçekleştirmeleri', 'Sualtı mayınlarıyla Manş Denizi\'nin en dar boğaz hattını tamamen kapatmaları', 'Yunan ateşi fırlatan kürekli kadırgalarla İspanyol gemilerini yakmaları'], 'John Hawkins\'in yeniden tasarladığı \'race-built\' İngiliz kalyonları, İspanyolların asker dolu yüksek kasaralı gemilerine yanaşmadan uzaktan topçu ateşiyle üstünlük kurmuştur.'),
  ('17. yüzyıldaki İngiliz-Hollanda Deniz Savaşları sırasında karmaşık filo çatışmalarını disipline etmek amacıyla İngiliz \'Savaş Talimatları\'yla kurumsallaştırılan ve gemilerin arka arkaya dizilerek borda ateşi açtığı taktik nedir?', 'Pruva hattı (hat muharebesi) düzeni', ['Yarım ay biçiminde kuşatıcı kanat düzeni', 'Üçlü kama şeklinde mahmuzlama düzeni', 'Dağınık kurt sürüsü sızma ve baskın düzeni'], 'Amiral Robert Blake döneminde şekillenen pruva hattı (line of battle) taktiği, kendi gemilerini vurmadan azami borda topçu ateşini düşman hattına yöneltmeyi sağlamış ve \'hat gemisi\' kavramını doğurmuştur.'),
  ('İkinci İngiliz-Hollanda Savaşı\'nda (1667) Thames Nehri ağzından içeri sızarak Kraliyet Donanması\'nın Chatham Tersanesi\'ndeki zinciri kırıp İngiliz sancak gemisi HMS Royal Charles\'ı yedekte Hollanda\'ya götüren amiral kimdir?', 'Michiel de Ruyter', ['Horatio Nelson', 'John Jervis', 'Pierre-André de Suffren'], 'Michiel de Ruyter\'in planladığı Medway (Chatham) Baskını, İngiliz denizcilik tarihinin kendi ana üssünde uğradığı en ağır aşağılanma olarak Breda Antlaşması\'nı hızlandırmıştır.'),
  ('1770 Çeşme Deniz Muharebesi\'nde sancak gemisi \'Burc-u Zafer\' Rus amiral gemisi \'Yevstafiy\' ile borda bordaya yanarken yaralı halde karaya yüzerek kurtulan ve ardından Limni\'yi Ruslardan geri alan komutan kimdir?', 'Cezayirli Gazi Hasan Paşa', ['Mezomorto Hüseyin Paşa', 'Koca Hüsrev Mehmed Paşa', 'Bozcaadalı Hasan Hüsnü Paşa'], 'Çeşme\'de dar limana girilmesine karşı çıkan Cezayirli Gazi Hasan Paşa, felaketin ardından Kaptan-ı Deryalığa getirilerek Osmanlı donanmasının yeniden inşasına önderlik etmiştir.'),
  ('Amerikan İç Savaşı sırasında 9 Mart 1862\'de Kuzey\'in döner taretli \'USS Monitor\' gemisi ile Güney\'in \'CSS Virginia\' (Merrimack) gemisi arasında gerçekleşen tarihin ilk zırhlı gemiler düellosu nerede yaşanmıştır?', 'Hampton Roads', ['Mobile Körfezi', 'Pearl Harbor', 'Manila Koyu'], 'Dört saat süren Hampton Roads çatışmasında hiçbir gemi diğerinin demir zırhını delip batıramamış, ancak ahşap savaş donanmalarının devri bir gecede kesin olarak kapanmıştır.'),
  ('1898 İspanyol-Amerikan Savaşı sırasında Küba\'daki Santiago ve Filipinler\'deki Manila Koyu muharebelerinde İspanyol filolarını hızla imha ederek okyanus aşırı sömürgeci güçler arasına katılan devlet hangisidir?', 'Amerika Birleşik Devletleri', ['Alman İmparatorluğu', 'İtalya Krallığı', 'Avusturya-Macaristan'], 'USS Maine zırhlısının Havana Limanı\'nda infilak etmesiyle başlayan savaşta Amiral George Dewey Manila\'da İspanyol Pasifik filosunu tek bir ABD askeri kaybetmeden yok etmiştir.'),
  ('1904-1905 Rus-Japon Savaşı\'nda Baltık Denizi\'nden 18.000 deniz mili yol kat ederek gelen Rus İkinci Pasifik Filosu\'nu Kore Boğazı\'nda T geçişi manevrasıyla neredeyse tamamen imha eden Japon amirali kimdir?', 'Tōgō Heihachirō', ['Isoroku Yamamoto', 'Chūichi Nagumo', 'Takeo Kurita'], '27-28 Mayıs 1905\'teki Tsushima (Tsuşima) Boğazı Deniz Muharebesi, modern çağda Asyalı bir devletin Avrupalı büyük bir gücün ana muharebe donanmasını yok ettiği sarsıcı zaferdir.'),
  ('1906 yılında İngiliz Kraliyet Donanması tarafından denize indirilen, buhar türbinli tahrik sistemi ve \'yalnızca tek kalibre büyük toplardan\' (all-big-gun) oluşan tasarımıyla önceki tüm zırhlıları bir anda demode bırakan gemi hangisidir?', 'HMS Dreadnought', ['HMS Hood', 'HMS Warrior', 'HMS Ark Royal'], 'Amiral Jackie Fisher\'ın öncülüğünde üretilen HMS Dreadnought o kadar büyük bir sıçrama yaratmıştır ki kendisinden önceki tüm zırhlılara \'ön-dretnot\', sonrakilere ise \'dretnot\' denilmiştir.'),
  ('Çanakkale Kara Savaşları devam ederken 12-13 Mayıs 1915 gecesi Morto Koyu\'na sızarak İngiliz \'HMS Goliath\' zırhlısını üç torpido atışıyla batıran Kıdemli Yüzbaşı Ahmet Saffet (Ohkay) komutasındaki Osmanlı muhribi hangisidir?', 'Muâvenet-i Milliye', ['Gayret-i Vataniye', 'Numûne-i Hamiyet', 'Berk-i Satvet'], 'Muâvenet-i Milliye\'nin Goliath\'ı batırması İngiliz Bahriye Birinci Deniz Lordu Fisher\'ın istifasına ve İngilizlerin değerli dretnotlarını Çanakkale\'den çekmesine neden olmuştur.'),
  ('31 Mayıs - 1 Haziran 1916\'da Danimarka açıklarında İngiliz Büyük Filosu (Jellicoe) ile Alman Açık Deniz Filosu (Scheer) arasında gerçekleşen ve I. Dünya Savaşı\'nın en büyük dretnot muharebesi olan çarpışma hangisidir?', 'Jutland (Skagerrak) Deniz Muharebesi', ['Falkland Adaları Deniz Muharebesi', 'Helgoland Körfezi Deniz Muharebesi', 'Otranto Boğazı Baraj Muharebesi'], 'Almanlar İngilizlerden daha fazla gemi batırarak taktik başarı iddia etse de İngiltere\'nin Kuzey Denizi ablukasını kıramamış ve Alman ana filosu savaş sonuna dek üslerine kapanmıştır.'),
  ('I. Dünya Savaşı\'nda Almanya\'nın Şubat 1917\'de yeniden başlattığı \'kısıtlamasız denizaltı (U-bot) savaşı\' ve bundan önce 1915\'te İngiliz yolcu gemisi RMS Lusitania\'nın batırılması hangi küresel siyasi sonucu doğurmuştur?', 'Amerika Birleşik Devletleri\'nin İtilaf Devletleri safında savaşa katılmasını', ['Rusya\'da Çarlık rejiminin güçlenerek Boğazları ele geçirmesini', 'İtalya\'nın Üçlü İttifak\'a sadık kalarak Fransa\'ya savaş açmasını', 'Japonya\'nın Pasifik\'teki Alman adalarını Almanya\'ya iade etmesini'], 'Alman denizaltılarının tarafsız ABD gemilerini de hedef alan kısıtlamasız U-bot kampanyası ve Zimmermann Telgrafı, Nisan 1917\'de ABD\'nin Almanya\'ya savaş ilan etmesine yol açmıştır.'),
  ('Kurtuluş Savaşı boyunca Sovyet Rusya\'nın Karadeniz limanlarından İnebolu, Samsun ve Trabzon\'a cephane ve silah taşıyan \'Gazanfer\', \'Şahin\', \'Rusumat No:4\' gibi kahraman nakliye filosu tarihe hangi adla geçmiştir?', 'İstiklal Deniz Nakliyat Grubu / Alemdar ve Taka Filosu', ['Şirket-i Hayriye Boğaziçi Filotillası', 'Donanma-yı Hümayun Zırhlı Tümeni', 'Akdeniz Garp Ocakları İmdat Filosu'], 'Özellikle Rüsumat No:4 vapuru Yunan gemilerine yakalanmamak için Ordu\'da kendi mürettebatınca batırılıp tehlike geçince yüzdürülerek cephane taşımayı sürdürmüştür.'),
  ('Kurtuluş Savaşı sırasında Ocak 1921\'de İstanbul\'dan kaçırılıp Karadeniz Ereğli\'ye götürülürken Fransız gambotu tarafından el konulan, ancak Türk mürettebatın Fransız muhafızları etkisiz hale getirerek geri aldığı ve İstiklal Savaşı\'nın tek deniz çatışmasını kazanan kurtarma gemisi hangisidir?', 'Alemdar Gemisi', ['Bandırma Vapuru', 'Gülcemal Vapuru', 'Ertuğrul Yatı'], 'Serdümen Recep Kahya\'nın şehit düştüğü Alemdar Destanı sonucunda Fransa, Ankara Hükümeti ile denizdeki ilk esir değişimi ve resmi mutabakatlardan birini yapmak zorunda kalmıştır.'),
  ('Mayıs 1942\'de ABD ve Japon donanmaları arasında gerçekleşen ve her iki tarafın suüstü gemilerinin birbirini hiç görmeden, birbirine tek bir top mermisi bile atmadan yalnızca uçak gemisi uçaklarıyla savaştığı tarihteki ilk muharebe hangisidir?', 'Mercan Denizi (Coral Sea) Muharebesi', ['Savo Adası Gece Muharebesi', 'Surigao Boğazı Deniz Muharebesi', 'Jutland Zırhlılar Muharebesi'], 'Mercan Denizi Muharebesi\'nde ABD \'USS Lexington\'ı kaybetse de Japonların Yeni Gine\'deki Port Moresby\'yi denizden işgal girişimini durdurarak Avustralya yolunu korumuştur.'),
  ('Ekim 1944\'te Filipinler\'in kurtarılması sırasında gerçekleşen, tonaj ve katılan personel bakımından dünya tarihinin en büyük deniz savaşı sayılan ve Japonların ilk kez organize \'Kamikaze\' uçak saldırılarını başlattığı muharebe hangisidir?', 'Leyte Körfezi Deniz Muharebesi', ['Guadalcanal Deniz Muharebesi', 'Doğu Solomonlar Muharebesi', 'Santa Cruz Adaları Savaşı'], 'Leyte Körfezi Muharebesi hem uçak gemisi savaşlarını hem de Surigao Boğazı\'nda tarihin son zırhlı gemi hat düellosunu barındırmış, Japon donanmasını stratejik güç olmaktan çıkarmıştır.'),
  ('1954 yılında suya indirilen ve dizel-elektrik tahrikinin su altında sınırlı kalma zorunluluğunu ortadan kaldırarak 1958\'de Kuzey Kutbu buzullarının altından su yüzüne çıkmadan geçen dünyanın ilk nükleer enerjili denizaltısı hangisidir?', 'USS Nautilus', ['USS George Washington', 'K-19 Hiroşima', 'Trieste II'], 'Amiral Hyman Rickover\'ın öncülüğünde geliştirilen USS Nautilus (SSN-571), denizaltıları \'ara sıra dalan suüstü teknesi\' olmaktan çıkarıp aylar boyu su altında kalabilen gerçek denizaltılara dönüştürmüştür.'),
  ('Ekim 1962\'de Sovyetler Birliği\'nin Küba\'ya nükleer başlık taşıyabilen orta menzilli füzeler yerleştiren gemiler göndermesi üzerine ABD Başkanı John F. Kennedy\'nin savaş ilanı sayılmaması için \'abluka\' yerine kullandığı deniz hukuku terimi nedir?', 'Deniz karantinası', ['Serbest transit geçiş', 'Müşterek avarya ilanı', 'Kabotaj tekeli'], 'Uluslararası hukukta \'abluka\' doğrudan savaş eylemi sayıldığından ABD yönetimi Küba çevresindeki deniz denetimini \'savunma amaçlı karantina\' olarak adlandırmış ve Sovyet gemileri geri dönmüştür.'),
  ('Mısır Hidivi Said Paşa ve İsmail Paşa dönemlerinde imtiyaz alarak 1859-1869 yılları arasında Süveyş Kanalı\'nın inşasını yöneten Fransız diplomat ve girişimci kimdir?', 'Ferdinand de Lesseps', ['George Goethals', 'Gustave Eiffel', 'Baron Haussmann'], 'Ferdinand de Lesseps Süveyş Kanalı\'ndaki başarısından cesaret alarak daha sonra Panama\'da da deniz seviyesinde havuzsuz kanal denemiş ancak heyelan ve sarıhumma yüzünden iflas etmiştir.'),
  ('Süveyş Kanalı\'nı Panama Kanalı gibi diğer kıstak kanallarından mühendislik bakımından ayıran en temel topoğrafik ve hidrolik özellik aşağıdakilerden hangisidir?', 'İki deniz arasında seviye farkı ve dağ engeli bulunmadığından kapaklı havuz (eklüz) içermemesi', ['Gemilerin kanal boyunca elektrikli lokomotiflerle beton raylar üzerinde çekilmesi', 'Kanal suyunun tatlı su göllerinden pompalanarak deniz seviyesinden 26 metre yukarı çıkarılması', 'Gelgit farkı 10 metreyi aştığı için günde yalnızca iki saat tek yönlü geçişe izin vermesi'], 'Akdeniz ile Kızıldeniz hemen hemen aynı su seviyesinde olduğundan Süveyş Kanalı acı göller üzerinden geçen düz, kapaksız (havuzsuz) bir su yoludur.'),
  ('Temmuz 1956\'da Mısır Cumhurbaşkanı Cemal Abdülnasır\'ın Asvan Barajı finansmanı çekilince Süveyş Kanalı Şirketi\'ni millîleştirmesi üzerine Mısır\'a karşı ortak askeri harekât başlatan üç devlet hangileridir?', 'İngiltere, Fransa ve İsrail', ['ABD, Sovyetler Birliği ve İtalya', 'Almanya, İspanya ve Portekiz', 'Türkiye, İran ve Irak'], '1956 Süveyş Krizi\'nde ABD ve SSCB\'nin sert diplomatik-ekonomik baskısı sonucu İngiltere ve Fransa geri çekilmek zorunda kalmış, kriz Avrupa\'nın eski sömürgeci güçlerinin gerileyişini simgelemiştir.'),
  ('Panama Kanalı\'ndan geçen gemilerin deniz seviyesinden yaklaşık 26 metre yüksekte yer alan hangi yapay tatlı su gölüne kapaklı havuzlarla (eklüzlerle) çıkarılıp diğer okyanusa indirildiği mühendislik sistemi uygulanmaktadır?', 'Gatun Gölü', ['Titicaca Gölü', 'Maracaibo Gölü', 'Managua Gölü'], 'Chagres Nehri önüne yapılan barajla oluşturulan Gatun Gölü, hem gemilerin kıstak sırtını aşmasını sağlar hem de havuz kapaklarının çalışması için gereken milyonlarca metreküp suyu temin eder.'),
  ('1977 yılında ABD Başkanı Jimmy Carter ile Panama lideri Omar Torrijos arasında imzalanan Torrijos-Carter Antlaşmaları uyarınca Panama Kanalı\'nın tam yönetimi ve egemenliği hangi tarihte Panama Cumhuriyeti\'ne devredilmiştir?', '31 Aralık 1999', ['15 Ağustos 1945', '26 Temmuz 1956', '9 Kasım 1989'], 'Torrijos-Carter Antlaşmaları ile ABD\'nin \'Kanal Bölgesi\' üzerindeki yaklaşık bir asırlık yönetimi 1999 sonunda barışçıl biçimde sona ermiş ve kanal tarafsızlık güvencesiyle Panama\'ya geçmiştir.'),
  ('Atlas Okyanusu ile Akdeniz\'i birbirine bağlayan Cebelitarık Boğazı\'nın kuzey yakasındaki stratejik Cebelitarık yarımadası, 1713 yılındaki hangi antlaşmayla İspanya tarafından İngiltere\'ye bırakılmıştır?', 'Utrecht Antlaşması', ['Amiens Antlaşması', 'Viyana Kongresi Senedi', 'Versay Barış Antlaşması'], 'İspanya Veraset Savaşı sırasında 1704\'te İngiliz-Hollanda donanmasınca ele geçirilen Cebelitarık Kayası, 1713 Utrecht Antlaşması\'yla İngiltere\'nin Akdeniz kapısındaki deniz üssü olmuştur.'),
  ('İtalya\'nın topuğu ile Arnavutluk kıyıları arasında yer alan, Adriyatik Denizi\'ni İyon Denizi\'ne bağlayan ve Venedik ile Osmanlı donanmalarının yüzyıllarca kontrolü için mücadele ettiği boğaz hangisidir?', 'Otranto Boğazı', ['Messina Boğazı', 'Bonifacio Boğazı', 'Kerç Boğazı'], 'Otranto Boğazı\'nın kapatılması Adriyatik kıyısındaki tüm limanların (Venedik, Trieste, Dubrovnik) Akdeniz\'le bağlantısını kestiğinden I. Dünya Savaşı\'nda bile buraya deniz barajı kurulmuştur.'),
  ('Karadeniz ile Azak Denizi\'ni birbirine bağlayan, batısında Kırım Yarımadası ve doğusunda Taman Yarımadası\'nın yer aldığı sığ stratejik su yolu hangisidir?', 'Kerç Boğazı', ['Kattegat Boğazı', 'Hürmüz Boğazı', 'Palk Boğazı'], 'Antik Çağ\'da \'Kimmer Bosporusu\' adıyla bilinen Kerç (Yenikale) Boğazı, Don Nehri iç su yoluyla bağlantılı Azak Denizi ticaretinin tek çıkış kapısıdır.'),
  ('Osmanlı İmparatorluğu\'nun İstanbul ve Çanakkale boğazları ile Karadeniz\'in tüm kıyılarına tek başına hâkim olduğu 15. yüzyıl sonundan 1774\'e kadar uyguladığı ve yabancı savaş/ticaret gemilerine boğazları kapalı tuttuğu ilke nasıl adlandırılır?', 'Osmanlı Devleti\'nin Kadim Kuralı', ['Açık Denizlerin Serbestisi İlkesi', 'Müşterek Boğazlar Komisyonu Rejimi', 'Karasuları Üç Mil Top Atımı Kuralı'], 'Karadeniz\'in bir \'Osmanlı iç gölü\' olduğu dönemde boğazlardan geçiş tamamen padişahın tek taraflı iradesine (Kadim Kural) bağlıydı ve yabancı bayraklı gemilere izin verilmiyordu.'),
  ('1774 yılında imzalanan Küçük Kaynarca Antlaşması, Türk Boğazları ve Karadeniz denizcilik tarihinde hangi köklü kırılmayı beraberinde getirmiştir?', 'Rus ticaret gemilerine Karadeniz\'de dolaşma ve Boğazlardan serbestçe geçme hakkının tanınmasını', ['İngiliz savaş zırhlılarının İstanbul Boğazı\'nda kalıcı deniz üssü kurmasına izin verilmesini', 'Çanakkale Boğazı\'ndaki tüm Osmanlı kıyı bataryalarının ve kalelerinin yıkılmasını', 'Karadeniz\'in tüm devletlerin denizaltı filolarına kayıtsız şartsız açılmasını'], 'Küçük Kaynarca Antlaşması ile Karadeniz\'in \'Türk gölü\' statüsü sona ermiş, ardından Avusturya, İngiltere ve Fransa da ticaret gemileri için Boğazlardan geçiş imtiyazı elde etmiştir.'),
  ('Hünkâr İskelesi Antlaşması\'nın 8 yıllık süresinin dolması ve Mısır Sorunu\'nun çözülmesinin ardından İngiltere, Fransa, Rusya, Avusturya, Prusya ve Osmanlı arasında imzalanarak Boğazlara ilk kez \'çok taraflı uluslararası statü\' kazandıran belge hangisidir?', '1841 Londra Boğazlar Sözleşmesi', ['1815 Viyana Kongresi Nihai Senedi', '1878 Ayastefanos Antlaşması', '1913 Londra Sınır Antlaşması'], '1841 Londra Boğazlar Sözleşmesi ile Osmanlı barış halindeyken Boğazların bütün yabancı savaş gemilerine kapalı olacağı (Rusya\'nın Hünkâr İskelesi ayrıcalığının bittiği) Avrupa devletlerince kararlaştırılmıştır.'),
  ('1856 Paris Barış Antlaşması\'nın 1841 Londra Boğazlar Sözleşmesi\'ne ek olarak Karadeniz\'in denizel statüsü hakkında getirdiği ve 1871 Londra Sözleşmesi\'ne dek yürürlükte kalan en önemli hüküm nedir?', 'Karadeniz\'in tarafsızlaştırılması, Osmanlı ve Rusya dahil kıyıdaşların savaş donanması ve tersane bulunduramaması', ['Karadeniz\'deki tüm ticaret limanlarının Fransız ve İngiliz gümrük memurlarınca yönetilmesi', 'Tuna Nehri ağzının taşlarla kapatılarak Orta Avrupa nehir gemilerinin Karadeniz\'e çıkışının önlenmesi', 'Rusya\'ya İstanbul Boğazı\'ndaki Büyükdere Koyu\'nda kömür ikmal istasyonu tahsis edilmesi'], 'Paris Antlaşması Rusya\'nın Karadeniz donanmasını yasaklayarak Boğazlar üzerindeki baskıyı hafifletmiş, ancak Rusya 1870 Fransız-Prusya Savaşı kargaşasından yararlanarak 1871\'de bu yasağı kaldırtmıştır.'),
  ('I. Dünya Savaşı başlarında 1915 yılında İngiltere ve Fransa\'nın, Rusya\'yı savaşta tutabilmek amacıyla gizli bir mutabakatla savaş sonunda Rusya\'ya bırakmayı kabul ettikleri stratejik bölge neresidir?', 'İstanbul ve Türk Boğazları', ['Süveyş Kanalı ve Sina Yarımadası', 'İzmir Limanı ve On İki Ada', 'Kıbrıs Adası ve İskenderun Körfezi'], '1915 İstanbul (Boğazlar) Gizli Antlaşması ile Çarlık Rusyası\'nın asırlık sıcak denizlere inme hedefi İngiltere ve Fransa tarafından onaylanmış, ancak 1917 Bolşevik Devrimi sonrası Sovyet yönetimi bu gizli antlaşmaları ifşa ederek reddetmiştir.'),
  ('28 Ocak 1920\'de Son Osmanlı Mebusan Meclisi tarafından kabul edilen Misak-ı Millî\'nin 4. maddesinde İstanbul ve Marmara\'nın güvenliği korunduğu takdirde Türk Boğazları hakkında hangi ilke benimsenmiştir?', 'Boğazların dünya ticaretine ve ulaşımına açılması konusunda ilgili devletlerle birlikte verilecek kararın geçerli olacağı', ['Boğazların tüm yabancı ticaret gemilerine dahi süresiz biçimde kapatılıp zincir çekileceği', 'Boğazların yönetiminin Milletler Cemiyeti mandası altında bağımsız bir şehir devletine bırakılacağı', 'Yalnızca Karadeniz\'e kıyısı olmayan devletlerin uçak gemilerinin Boğazlardan serbestçe geçebileceği'], 'Misak-ı Millî, başkent İstanbul ve Marmara Denizi\'nin her türlü tehlikeden uzak tutulması şartıyla Boğazların uluslararası ticaret trafiğine açık tutulmasına gerçekçi ve barışçıl bir yaklaşım sergilemiştir.'),
  ('Türkiye Cumhuriyeti\'nin 10 Nisan 1936\'da Lozan Boğazlar Sözleşmesi\'nin imzacılarına nota vererek Boğazlar rejiminin değiştirilmesini talep ederken dayandığı temel uluslararası güvenlik gerekçesi neydi?', 'İtalya\'nın Habeşistan\'ı işgali, On İki Ada\'yı silahlandırması ve Almanya\'nın Ren bölgesine girmesiyle kolektif güvenliğin çökmesi', ['Süveyş Kanalı\'nın kum fırtınaları nedeniyle kapanması üzerine tüm okyanus trafiğinin Karadeniz\'e yönelmesi', 'Yunanistan\'ın Balkan Antantı\'ndan çekilerek Bulgaristan ile İstanbul\'a karşı ortak donanma kurması', 'ABD\'nin Monroe Doktrini uyarınca Akdeniz\'deki tüm boğazların silahsızlandırılmasını istemesi'], '1930\'lu yıllarda Milletler Cemiyeti\'nin saldırgan devletleri durduramaması, Lozan\'daki kolektif garanti sistemini geçersiz kılmış; Türkiye silah zoruyla değil, hukuk ve diplomasi yoluyla (rebus sic stantibus ilkesiyle) revizyon istemiştir.'),
  ('1936 Montrö Boğazlar Sözleşmesi\'nin ticaret gemilerinin barış zamanında İstanbul ve Çanakkale boğazlarından transit geçişine ilişkin temel kuralı aşağıdakilerden hangisidir?', 'Bayrak ve yük ne olursa olsun gece ve gündüz, sağlık denetimi dışında hiçbir formalite olmaksızın tam geçiş serbestisi', ['Yalnızca Karadeniz\'e kıyısı olan devletlerin ticaret gemilerine gündüz saatlerinde geçiş izni verilmesi', 'Transit geçen tüm ticaret gemilerinin yüklerinin yüzde onunu İstanbul Gümrüğü\'ne vergi olarak bırakması', 'Ticaret gemilerinin Boğazlardan geçebilmesi için en az bir ay önceden diplomatik nota verilmesi'], 'Montrö Sözleşmesi\'nin 2. maddesi uyarınca barış zamanında ticaret gemileri tam geçiş ve seyrüsefer özgürlüğüne sahip olup kılavuzluk ve römorkaj isteğe bağlı tutulmuştur.'),
  ('16. yüzyılda Akdeniz ile Kızıldeniz arasında bir kanal açılması fikrini gündeme getiren Osmanlı devlet adamı kimdir?', 'Sokullu Mehmed Paşa', ['Pargalı İbrahim Paşa', 'Köprülü Mehmed Paşa', 'Merzifonlu Kara Mustafa Paşa'], 'Sadrazam Sokullu Mehmed Paşa, Portekizlilerin Hint Okyanusu\'ndaki faaliyetlerine karşı Osmanlı donanmasını Kızıldeniz\'e indirmek amacıyla Süveyş\'te kanal projesi tasarlamıştır.'),
  ('Süveyş Kanalı\'nın açıldığı 1869 yılında Mısır\'ın başında bulunan ve görkemli açılış törenlerini düzenleyen hidiv kimdir?', 'İsmail Paşa', ['Mehmed Ali Paşa', 'Said Paşa', 'Abbas Hilmi Paşa'], 'Hidiv İsmail Paşa, Kasım 1869\'da Avrupalı hükümdarların da katıldığı büyük törenlerle Süveyş Kanalı\'nı hizmete açmıştır.'),
  ('1875 yılında mali krize giren Mısır Hidivi İsmail Paşa\'nın Süveyş Kanalı hisselerini satın alarak bölgede söz sahibi olan devlet hangisidir?', 'Birleşik Krallık', ['Fransa Cumhuriyeti', 'Rus İmparatorluğu', 'Alman İmparatorluğu'], 'İngiltere Başbakanı Benjamin Disraeli, Rothschild ailesinden sağladığı krediyle Mısır\'ın kanal hisselerini satın alarak Hindistan yolunun kontrolünü güçlendirmiştir.'),
  ('1956 yılında Süveyş Kanalı Şirketi\'ni millileştirerek Süveyş Krizi\'nin başlamasına yol açan Mısır lideri kimdir?', 'Cemal Abdülnasır', ['Enver Sedat', 'Muhammed Necib', 'Hüsnü Mübarek'], 'Mısır Cumhurbaşkanı Cemal Abdülnasır, Asvan Barajı\'nın finansmanı için 26 Temmuz 1956\'da Süveyş Kanalı\'nı millileştirdiğini ilan etmiştir.'),
  ('1956 Süveyş Krizi sırasında Mısır\'a karşı askeri harekat düzenleyen üçlü ittifak hangi devletlerden oluşmuştur?', 'İngiltere, Fransa ve İsrail', ['ABD, İngiltere ve Fransa', 'Fransa, İtalya ve İsrail', 'İngiltere, ABD ve Ürdün'], 'Kanalın millileştirilmesi üzerine İngiltere ve Fransa, İsrail ile gizli Sevres Protokolü\'nü yaparak Mısır\'a askeri müdahalede bulunmuştur.'),
  ('Süveyş Kanalı\'nın teknik yapısı ile Panama Kanalı\'nın teknik yapısı karşılaştırıldığında Süveyş Kanalı\'nı ayıran temel özellik nedir?', 'Havuz ve kapak sistemi olmadan deniz seviyesinde açılmış olması', ['Gemileri yükseltmek için çok katmanlı su havuzları kullanması', 'Tatlı su göllerinden beslenen yapay şelaleler içermesi', 'Yalnızca gelgit saatlerinde tek yönlü geçişe izin vermesi'], 'Süveyş Kanalı, Akdeniz ve Kızıldeniz arasındaki seviye farkının çok az olması sayesinde kapaksız (havuzsuz) olarak deniz seviyesinde inşa edilmiştir.'),
  ('1881 yılında Panama Kanalı\'nı deniz seviyesinde inşa etmek için ilk büyük girişimi başlatan ancak salgın hastalıklar ve mali kriz nedeniyle başarısız olan ülke hangisidir?', 'Fransa', ['İspanya', 'Birleşik Krallık', 'Hollanda'], 'Süveyş Kanalı\'ndaki başarısından cesaret alan Ferdinand de Lesseps liderliğindeki Fransız şirketi 1881\'de kazılara başlamış, ancak 1889\'da iflas etmiştir.'),
  ('Fransızların Panama Kanalı inşaatında yirmi binden fazla işçinin ölümüyle sonuçlanan başarısızlığında en etkili olan iki salgın hastalık hangileridir?', 'Sarıhumma ve sıtma', ['Kolera ve çiçek hastalığı', 'Veba ve tifüs salgını', 'İspanyol gribi ve dizanteri'], 'Tropikal iklimde sivrisineklerin taşıdığı sarıhumma ve sıtma hastalıkları, bulaşma yolları henüz tam bilinmediği için Fransız girişimini felakete sürüklemiştir.'),
  ('1903 yılında Panama\'nın hangi devletten ayrılarak bağımsızlığını ilan etmesi üzerine ABD kanal bölgesi imtiyazını elde etmiştir?', 'Kolombiya', ['Venezuela', 'Meksika', 'Nikaragua'], 'Kolombiya Senatosu kanal antlaşmasını reddedince ABD, Panama\'daki ayrılıkçı hareketi desteklemiş ve kurulan yeni Panama devletiyle antlaşma imzalamıştır.'),
  ('Panama Kanalı\'nın inşasını devralarak projenin başarıyla tamamlanmasında siyasi liderlik üstlenen ABD Başkanı kimdir?', 'Theodore Roosevelt', ['Woodrow Wilson', 'Abraham Lincoln', 'Franklin D. Roosevelt'], 'Başkan Theodore Roosevelt, Amerikan deniz gücünün iki okyanus arasında hızla geçiş yapabilmesi için Panama Kanalı projesini bizzat sahiplenmiştir.'),
  ('Panama Kanalı\'ndan geçen bir gemi, okyanus seviyesinden yaklaşık 26 metre yukarıda bulunan hangi yapay göl seviyesine çıkarılıp tekrar indirilir?', 'Gatun Gölü', ['Asvan Gölü', 'Titicaca Gölü', 'Nikaragua Gölü'], 'Chagres Nehri\'nin önüne kurulan barajla oluşturulan Gatun Gölü, Panama Kanalı\'nın havuzlu yükseltme ve indirme sisteminin merkezini oluşturur.'),
  ('1898 İspanya-ABD Savaşı sırasında hangi Amerikan zırhlısının San Francisco\'dan Küba\'ya ulaşmak için Horn Burnu\'nu dolaşarak 67 gün harcaması Panama Kanalı\'nın askeri gerekliliğini kanıtlamıştır?', 'USS Oregon', ['USS Maine', 'USS Missouri', 'USS Constitution'], 'USS Oregon zırhlısının Güney Amerika\'yı dolaşarak yaptığı uzun yolculuk, ABD kamuoyunda ve donanmasında okyanuslar arası kanal ihtiyacını kesinleştirmiştir.'),
  ('Osmanlı Padişahı II. Mahmud\'u 1833\'te Rusya ile Hünkar İskelesi Antlaşması\'nı imzalamaya zorlayan temel iç gelişme nedir?', 'Kavalalı Mehmed Ali Paşa İsyanı', ['Yeniçeri Ocağı\'nın ayaklanması', 'Yunan bağımsızlık isyanının başlaması', 'Tepedelenli Ali Paşa\'nın başkaldırısı'], 'Mısır Valisi Kavalalı Mehmed Ali Paşa\'nın ordularının Kütahya\'ya kadar ilerlemesi ve Avrupalı devletlerin yardım etmemesi üzerine II. Mahmud, "denize düşen yılana sarılır" diyerek Rusya\'dan destek istemiştir.'),
  ('1833 Hünkar İskelesi Antlaşması\'nın Avrupalı devletleri en çok endişelendiren gizli maddesi neyi öngörmüştür?', 'Osmanlı Devleti\'nin Rusya savaşa girerse Çanakkale Boğazı\'nı yabancı savaş gemilerine kapatmasını', ['Rus savaş gemilerine Akdeniz\'de kalıcı deniz üssü kurma hakkı tanınmasını', 'Boğazların yönetiminin Osmanlı ve Rus ortak komisyonuna bırakılmasını', 'İngiliz ve Fransız ticaret gemilerinden Boğaz geçişlerinde iki kat vergi alınmasını'], 'Gizli maddeye göre Rusya bir saldırıya uğrarsa Osmanlı asker göndermek yerine Çanakkale Boğazı\'nı diğer devletlerin savaş gemilerine kapatarak Rusya\'nın Karadeniz güvenliğini sağlayacaktı.'),
  ('1841 Londra Boğazlar Sözleşmesi\'nin "Osmanlı Devleti barış zamanında Boğazları tüm yabancı savaş gemilerine kapatacaktır" hükmü hangi devletin Hünkar İskelesi ile elde ettiği üstünlüğü sona erdirmiştir?', 'Rus İmparatorluğu', ['Birleşik Krallık', 'Avusturya İmparatorluğu', 'Prusya Krallığı'], '1841 Londra Boğazlar Sözleşmesi ile Rusya, Karadeniz\'e hapsolmuş ve Hünkar İskelesi Antlaşması ile elde ettiği ayrıcalıklı güvenlik konumunu kaybetmiştir.'),
  ('1841 Londra Boğazlar Sözleşmesi Osmanlı Devleti\'nin egemenlik hakları açısından nasıl bir dönüşüm yaratmıştır?', 'Boğazlar üzerindeki mutlak egemenliğin sona erip uluslararası statü döneminin başlaması', ['Boğazlardan geçen ticaret gemilerini denetleme yetkisinin tamamen kaybedilmesi', 'İstanbul ve Çanakkale kıyılarının askeri tahkimattan tamamen arındırılması', 'Boğazların idaresinin Milletler Cemiyeti benzeri bir komisyona devredilmesi'], 'Londra Boğazlar Sözleşmesi ile Boğazların statüsü ilk kez çok taraflı bir Avrupa antlaşmasıyla belirlenmiş ve Osmanlı\'nın tek taraflı karar alma yetkisi kısıtlanmıştır.'),
  ('1920 tarihli Sevr Antlaşması taslağında Boğazların yönetimi konusunda öngörülen ve Türk egemenliğini tamamen yok sayan düzenleme neydi?', 'Kendine ait bütçesi, bayrağı ve zabıtası olan uluslararası bir Boğazlar Komisyonu kurulması', ['Boğazların idaresinin doğrudan Yunanistan ve İngiltere ortak komutanlığına verilmesi', 'Boğazların sadece Karadeniz\'e kıyısı olan devletlerin oluşturacağı kurula bırakılması', 'İstanbul Boğazı\'nın İngiltere\'ye, Çanakkale Boğazı\'nın ise Fransa\'ya kiralanması'], 'Sevr\'de Türk temsilcisinin başlangıçta yer bile almadığı, ayrı bayrağı ve bütçesi bulunan bağımsız bir Boğazlar Komisyonu öngörülmüştü.'),
  ('28 Ocak 1920\'de kabul edilen Misak-ı Milli kararlarında İstanbul ve Marmara\'nın güvenliği sağlandığı takdirde Boğazlar hakkında hangi ilke benimsenmiştir?', 'İlgili devletlerin ortak kararıyla Boğazların dünya ticaret ve ulaşımına açılması', ['Boğazlardan hiçbir yabancı ticaret gemisinin geçişine kesinlikle izin verilmemesi', 'Boğazların askeri denetiminin Karadeniz devletleri arasında paylaştırılması', 'Boğazlardan geçiş hakkının yalnızca müttefik devletlerin donanmalarına tanınması'], 'Misak-ı Milli\'nin dördüncü maddesi, İstanbul ve Marmara\'nın güvenliği koşuluyla Boğazların dünya ticaret ve ulaşımına açılması konusunda ilgili devletlerle verilecek kararın geçerli olacağını belirtmiştir.'),
  ('16 Mart 1921 tarihli Moskova Antlaşması\'nda TBMM Hükümeti ile Sovyet Rusya, Boğazların nihai statüsünün kimler tarafından belirlenmesini kabul etmiştir?', 'Karadeniz\'e kıyısı olan devletlerin temsilcilerinden oluşacak bir konferans', ['Milletler Cemiyeti Konseyi bünyesinde kurulacak daimi deniz komisyonu', 'Lozan\'da toplanacak olan İtilaf Devletleri ve TBMM ortak heyeti', 'Yalnızca Türkiye ve Sovyet Rusya dışişleri bakanlıklarının ikili kurulu'], 'Moskova Antlaşması\'nın 5. maddesinde, Türkiye\'nin egemenliğine ve İstanbul\'un güvenliğine zarar vermeden Boğazlar statüsünün Karadeniz\'e kıyıdaş devletlerce hazırlanması öngörülmüştür.'),
  ('1923 Lozan Boğazlar Sözleşmesi\'nin Türkiye\'nin ulusal güvenliğini ve egemenliğini sınırlandıran en önemli hükmü hangisidir?', 'Boğazların her iki yakasının askerden ve tahkimattan arındırılması', ['Boğazlar Komisyonu\'nda Türkiye\'nin hiçbir temsilci bulunduramaması', 'Türk ticaret gemilerinin Boğazlardan geçişte komisyona vergi ödemesi', 'İstanbul şehrinin tamamının uluslararası serbest bölge ilan edilmesi'], 'Lozan Boğazlar Sözleşmesi uyarınca Çanakkale ve İstanbul Boğazlarının her iki yakasında belirlenen bölgeler ile Marmara\'daki bazı adalar askersizleştirilmişti.'),
  ('1930\'lu yılların ortalarında Türkiye\'yi Lozan Boğazlar Sözleşmesi\'nin değiştirilmesi için Milletler Cemiyeti\'ne başvurmaya yönelten uluslararası gelişmeler nelerdir?', 'İtalya\'nın Habeşistan\'ı işgali, Japonya\'nın Mançurya\'ya saldırısı ve Almanya\'nın silahlanması', ['İkinci Dünya Savaşı\'nın resmen başlaması ve Fransa\'nın Alman ordularınca işgali', 'Yunanistan ile Türkiye arasında nüfus mübadelesi krizinin yeniden alevlenmesi', 'Sovyetler Birliği\'nin Kars ve Ardahan üzerinde resmen toprak talebinde bulunması'], 'Silahsızlanma konferanslarının başarısız olması, İtalya\'nın Habeşistan\'a saldırması ve Almanya\'nın Ren bölgesine asker sokması, Lozan\'daki ortak güvenlik garantilerini geçersiz kılmıştır.'),
  ('Montrö Boğazlar Konferansı\'nda Türkiye Cumhuriyeti heyetine başkanlık eden dönemin Dışişleri Bakanı kimdir?', 'Tevfik Rüştü Aras', ['İsmet İnönü', 'Şükrü Saracoğlu', 'Numan Menemencioğlu'], 'Atatürk döneminin uzun süreli Dışişleri Bakanı Tevfik Rüştü Aras, Montrö\'de Türk heyetine başkanlık ederek diplomatik müzakereleri yürütmüştür.'),
  ('Montrö Boğazlar Sözleşmesi\'nin yürürlüğe girmesiyle birlikte Türkiye\'nin askeri açıdan attığı ilk somut adım ne olmuştur?', 'Türk ordusunun Boğazların askersizleştirilmiş bölgelerine girerek tahkimat kurması', ['Karadeniz girişine yabancı ticaret gemilerini durduracak deniz mayınları döşenmesi', 'İstanbul ve Çanakkale\'de yabancı devletlere ait tüm liman tesislerinin kapatılması', 'Sovyetler Birliği ile ortak bir Karadeniz savunma donanmasının oluşturulması'], '20 Temmuz 1936 gecesi sözleşmenin imzalanmasının hemen ardından Türk askeri birlikleri yıllardır askersiz tutulan Çanakkale ve İstanbul Boğazları kıyılarına girmiştir.'),
  ('Montrö Boğazlar Sözleşmesi\'ne göre barış zamanında yabancı ticaret gemilerinin Boğazlardan geçiş rejimi nasıldır?', 'Bayrak ve yük ne olursa olsun gündüz ve gece tam geçiş serbestisi vardır', ['Yalnızca Karadeniz\'e kıyısı olan ülkelerin ticaret gemileri serbestçe geçebilir', 'Her ticaret gemisi geçişten on beş gün önce Türkiye\'den diplomatik izin almalıdır', 'Ticaret gemileri yalnızca gündüz saatlerinde ve Türk kılavuz kaptanla geçebilir'], 'Montrö\'nün 2. maddesi uyarınca barış zamanında ticaret gemileri, bayrak ve yük ne olursa olsun sadece sağlık denetimi ve belirli rüsumlar çerçevesinde tam geçiş özgürlüğüne sahiptir.'),
  ('Türkiye\'nin 1936\'da Boğazlar sorununu oldubitti ve işgal yerine diplomatik nota ve uluslararası konferans yoluyla çözmesi dış politikada nasıl bir etki yaratmıştır?', 'Türkiye\'nin barışçı ve hukuka bağlı dış politika saygınlığını artırmıştır', ['Türkiye\'nin Balkan Antantı\'ndaki müttefikleriyle ilişkilerinin kopmasına yol açmıştır', 'İngiltere ve Fransa\'nın Türkiye\'ye ekonomik ambargo uygulamasına neden olmuştur', 'Milletler Cemiyeti\'nin Türkiye\'nin üyelik başvurusunu geri çevirmesiyle sonuçlanmıştır'], 'Almanya ve İtalya\'nın tek taraflı işgaller yaptığı bir dönemde Türkiye\'nin hukuk yoluyla haklarını alması uluslararası alanda büyük takdir toplamıştır.'),
  ('Osmanlı İmparatorluğu\'nun son döneminden Cumhuriyet\'e Boğazlar rejimini düzenleyen belgelerin kronolojik sıralaması hangisinde doğru verilmiştir?', 'Hünkar İskelesi - Londra - Lozan - Montrö', ['Londra - Hünkar İskelesi - Lozan - Montrö', 'Hünkar İskelesi - Lozan - Londra - Montrö', 'Londra - Hünkar İskelesi - Montrö - Lozan'], 'Boğazlar rejimi sırasıyla 1833 Hünkar İskelesi, 1841 Londra, 1923 Lozan ve 1936 Montrö sözleşmeleri ile şekillenmiştir.'),
  ('Montrö Boğazlar Sözleşmesi\'nin süresi ve yürürlük rejimi hakkında belirlenen temel hukuki ilke nedir?', 'Sözleşme yirmi yıl süreli yapılmış ancak fesih bildirimi olmadıkça yürürlükte kalması kararlaştırılmıştır', ['Sözleşmenin her on yılda bir Birleşmiş Milletler tarafından yeniden oylanması zorunlu kılınmıştır', 'Sözleşmenin elli yıl sonunda kendiliğinden sona erip Lozan rejimine dönülmesi kararlaştırılmıştır', 'Sözleşme yalnızca beş yıllık geçici bir askeri ateşkes protokolü olarak düzenlenmiştir'], 'Montrö\'nün 28. maddesine göre sözleşme yirmi yıl sürelidir; ancak taraflardan biri sürenin bitiminden iki yıl önce fesih ihbarında bulunmadıkça yürürlükte kalmaya devam eder ve ticaret gemilerinin serbest geçiş ilkesi süresizdir.'),
  ('7-8 Mart 1915 gecesi Karanlık Liman\'a kıyıya paralel şekilde yirmi altı mayın döşeyerek 18 Mart zaferinin zeminini hazırlayan Nusret Mayın Gemisi\'nin komutanı kimdir?', 'Yüzbaşı Tophaneli Hakkı Bey', ['Yüzbaşı Rauf Orbay', 'Binbaşı Ali Çetinkaya', 'Albay Cevat Çobanlı'], 'Kalp rahatsızlığına rağmen görevi bırakmayan Yüzbaşı Tophaneli İsmail Hakkı Bey, Mayın Grup Komutanı Nazmi Bey ile birlikte 7-8 Mart gecesi tarihi mayınlama harekatını gerçekleştirmiştir.'),
  ('Nusret Mayın Gemisi\'nin Karanlık Liman\'a döşediği 11. mayın hattının İtilaf donanması tarafından önceden fark edilememesinin taktiksel nedeni nedir?', 'Mayınların boğazı enlemesine kesmek yerine Erenköy Koyu\'nda kıyıya paralel dökülmesi', ['Mayınların o dönem ilk kez kullanılan manyetik taban sensörleriyle su dibine gizlenmesi', 'Mayın hattının sadece gece saatlerinde su yüzüne çıkacak şekilde kurgulanması', 'Mayınların Çanakkale Boğazı\'nın Karadeniz çıkışındaki sığ sulara yerleştirilmesi'], 'İtilaf keşif uçakları ve mayın tarama gemileri boğaza dik hatları ararken, Nusret\'in manevra sahası olan Erenköy Koyu\'na kıyıya paralel döşediği 26 mayın gizli kalmıştır.'),
  ('18 Mart 1915 Çanakkale Deniz Zaferi\'ndeki üstün komutanlığı nedeniyle "18 Mart Kahramanı" unvanıyla anılan Müstahkem Mevki Komutanı kimdir?', 'Cevat Çobanlı Paşa', ['Esat Bülkat Paşa', 'Kazım Karabekir Paşa', 'Fevzi Çakmak Paşa'], 'Çanakkale Müstahkem Mevki Komutanı Tümgeneral Cevat (Çobanlı) Paşa, topçu bataryalarının ve mayın hatlarının koordinasyonundaki başarısıyla "18 Mart Kahramanı" unvanını almıştır.'),
  ('İtilaf Devletleri\'nin 1915 yılında Çanakkale Boğazı\'nı denizden geçmek istemelerinin temel stratejik amaçlarından biri nedir?', 'Ekonomik ve askeri darboğaz yaşayan müttefikleri Çarlık Rusyası\'na yardım ulaştırmak', ['Süveyş Kanalı\'nı Osmanlı ordusunun elinden geri alarak Mısır\'ı kurtarmak', 'Almanya\'nın Baltık Denizi\'ndeki denizaltı üslerini doğrudan bombalamak', 'İtalya\'nın İttifak Devletleri safında savaşa girmesini kesin olarak sağlamak'], 'İngiltere ve Fransa, İstanbul\'u alıp Osmanlı\'yı savaş dışı bırakmanın yanı sıra Boğazlar üzerinden Çarlık Rusyası\'na silah ve mühimmat gönderip Rus buğdayını Avrupa\'ya taşımayı amaçlamıştır.'),
  ('Birinci Dünya Savaşı başında Akdeniz\'de İngiliz donanmasından kaçarak Çanakkale Boğazı\'ndan Osmanlı Devleti\'ne sığınan ve Yavuz ile Midilli adları verilen iki Alman savaş gemisinin özgün adları nedir?', 'Goeben ve Breslau', ['Bismarck ve Tirpitz', 'Scharnhorst ve Gneisenau', 'Emden ve Königsberg'], 'Amiral Souchon komutasındaki Goeben ve Breslau gemileri Ağustos 1914\'te Çanakkale\'den girmiş, Osmanlı Devleti bu gemileri satın aldığını açıklayarak Yavuz ve Midilli adlarını vermiştir.'),
  ('18 Mart 1915\'te İtilaf donanmasının Çanakkale Boğazı\'nı denizden geçememesi savaşın gidişatında doğrudan hangi askeri aşamaya geçilmesine neden olmuştur?', 'Gelibolu Yarımadası\'na 25 Nisan 1915\'te geniş çaplı kara çıkarması yapılmasına', ['İtilaf Devletleri\'nin Çanakkale cephesini tamamen kapatıp barış istemesine', 'Rus Karadeniz Donanması\'nın İstanbul Boğazı\'nı tek başına ele geçirmesine', 'Bulgaristan\'ın İtilaf Devletleri yanında Osmanlı\'ya karşı savaşa katılmasına'], 'Boğazın yalnızca donanmayla geçilemeyeceğini anlayan İtilaf komutanlığı, tabyaları karadan susturmak amacıyla 25 Nisan 1915\'te Gelibolu\'ya kara çıkarması başlatmıştır.'),
  ('Çanakkale Deniz ve Kara Zaferlerinin dünya tarihi açısından yarattığı en büyük siyasal sonuçlardan biri nedir?', 'Yardım alamayan Çarlık Rusyası\'nda 1917 Bolşevik İhtilali\'nin patlak vermesini hızlandırması', ['Birinci Dünya Savaşı\'nın 1915 yılı sonbaharında kesin barışla sona ermesi', 'ABD\'nin Almanya ve Osmanlı Devleti yanında savaşa girmeye karar vermesi', 'Osmanlı Devleti\'nin Balkan Savaşları\'nda kaybettiği tüm toprakları geri alması'], 'Boğazların kapalı kalması nedeniyle müttefiklerinden ikmal alamayan Çarlık Rusyası\'nda ekonomik ve askeri çöküş derinleşmiş, bu durum 1917 devrimlerine zemin hazırlamıştır.'),
  ('Osmanlı İmparatorluğu döneminde Türk limanları arasındaki deniz ticaretinin büyük ölçüde yabancı gemilerin eline geçmesinin temel tarihsel nedeni nedir?', 'Yabancı devletlere tanınan kapitülasyon ayrıcalıkları', ['Osmanlı ülkesinde gemi inşa edecek kereste bulunmaması', 'Akdeniz ve Karadeniz\'de hiç Osmanlı limanının olmaması', 'Osmanlı tebaasına denize açılmanın kanunen yasaklanması'], 'Kapitülasyonlar yoluyla Avrupalı devletlere tanınan gümrük, vergi ve liman ayrıcalıkları yerli deniz ticaretini rekabet edemez hale getirmişti.'),
  ('Türkiye\'nin kabotaj hakkını tam olarak elde etmesinin uluslararası hukuk açısından önünü açan 1923 tarihli antlaşma hangisidir?', 'Lozan Barış Antlaşması', ['Ankara İtilafnamesi', 'Gümrü Barış Antlaşması', 'Kars Antlaşması'], 'Lozan Barış Antlaşması\'yla kapitülasyonların kaldırılması ve ticaret sözleşmesindeki geçiş süresinin tamamlanmasıyla Türkiye kendi sularında kabotaj tekelini kurma hakkını kazanmıştır.'),
  ('815 sayılı Kabotaj Kanunu uyarınca Türkiye kıyılarında kılavuzluk, römorkörcülük, dalgıçlık, tayfalık ve kaptanlık gibi deniz mesleklerini kimler icra edebilir?', 'Yalnızca Türkiye Cumhuriyeti vatandaşları', ['Karadeniz Ekonomik İşbirliği üyesi ülke yurttaşları', 'Uluslararası Denizcilik Örgütü sertifikalı tüm yabancılar', 'Akdeniz\'e kıyısı olan dost devletlerin gemicileri'], 'Kabotaj Kanunu yalnızca gemi işletmeciliğini değil, Türk karasularındaki dalgıçlık, kılavuzluk, kaptanlık, çarkçılık ve tayfalık gibi meslekleri de Türk vatandaşlarına tahsis etmiştir.'),
  ('Lozan Barış Antlaşması 1923\'te imzalandığı halde Kabotaj Kanunu\'nun 1 Temmuz 1926\'da yürürlüğe girmesinin hukuki sebebi nedir?', 'Lozan Ticaret Sözleşmesi ile bazı yabancı kumpanyalara tanınan geçiş süresinin beklenmesi', ['Türkiye Büyük Millet Meclisi\'nin 1926 yılına kadar denizcilik yasasını reddetmesi', 'İngiliz donanmasının İstanbul Limanı\'nı 1926 yazına kadar boşaltmamış olması', 'Milletler Cemiyeti\'nin Türkiye\'ye üç yıllık deniz ticareti yasağı uygulaması'], 'Lozan\'a ek Ticaret Sözleşmesi uyarınca Türk limanlarında düzenli sefer yapan bazı İtilaf gemilerine tanınan geçici sürenin dolmasıyla 1 Temmuz 1926\'da tam kabotaj uygulamasına geçilmiştir.'),
  ('1926 yılında Avrupa limanlarında Türkiye\'nin tanıtımını yapan Karadeniz Vapuru\'nun kaptanlığını üstlenen deneyimli Türk denizcisi kimdir?', 'Lütfi Kaptan', ['Rauf Orbay', 'Şükran Kaptan', 'İsmail Hakkı Durusu'], 'Süvari Lütfi (Ülkümen) Kaptan yönetimindeki Karadeniz Vapuru, yaklaşık üç ay süren 10 bin millik Avrupa tanıtım seferini tek bir kaza yapmadan başarıyla tamamlamıştır.'),
  ('19 Mayıs 1919\'da Mustafa Kemal Paşa\'yı İstanbul\'dan Samsun\'a götüren Bandırma Vapuru\'nun kaptanı kimdir?', 'İsmail Hakkı Durusu', ['Tophaneli Hakkı Bey', 'Ahmet Saffet Ohkay', 'Gazanfer Bilge'], 'Kaptan İsmail Hakkı (Durusu), eski ve yıpranmış Bandırma Vapuru\'nu pusula sorunlarına ve Karadeniz fırtınasına rağmen güvenle Samsun\'a ulaştırmıştır.'),
  ('Kurtuluş Savaşı sırasında Ocak 1921\'de İstanbul\'dan kaçırılarak Karadeniz\'e açılan, Fransızların el koyma girişimini mürettebatının direnişiyle püskürterek İstiklal Madalyası alan tek gemimiz hangisidir?', 'Alemdar Kurtarma Gemisi', ['Nusret Mayın Gemisi', 'Preveze Gambotu', 'Aydınreis Gambotu'], 'Ereğli açıklarında Fransız gambotuna karşı destansı bir direniş gösteren Alemdar gemisi, Kurtuluş Savaşı\'nın ilk deniz anlaşmasını sağlamış ve İstiklal Madalyası ile ödüllendirilmiştir.'),
  ('Kurtuluş Savaşı yıllarında Karadeniz üzerinden gelen cephanenin Anadolu içlerine taşındığı "İstiklal Yolu"nun başlangıç noktası olan ve kayıkçılarının kahramanlığıyla İstiklal Madalyası alan kıyı ilçemiz hangisidir?', 'İnebolu', ['Sinop', 'Mudanya', 'Ayvalık'], 'Beyaz Şeritli İstiklal Madalyası sahibi tek ilçe olan Kastamonu\'nun İnebolu ilçesi, denizden gelen cephanenin kayıklarla kıyıya çıkarılıp kağnılarla Ankara\'ya sevk edildiği ana kapı olmuştur.'),
  ('1920 yılında Amerika Birleşik Devletleri\'nin New York limanına giderek Atlas Okyanusu\'nu aşan ve ABD sularında Türk bayrağını dalgalandıran ilk Türk yolcu gemisi hangisidir?', 'Gülcemal Vapuru', ['Karadeniz Vapuru', 'Ankara Vapuru', 'Ege Vapuru'], 'Osmanlı Seyr-i Sefain İdaresi\'ne ait Gülcemal Vapuru, Ekim 1920\'de İstanbul\'dan kalkıp New York\'a ulaşarak Atlantik\'i geçen ilk Türk yolcu vapuru unvanını kazanmıştır.'),
  ('Mustafa Kemal Atatürk\'ün 1 Kasım 1937 tarihli TBMM açılış konuşmasında "En güzel coğrafi vaziyette ve üç tarafı denizle çevrili olan Türkiye; endüstrisi, ticareti ve sporu ile en ileri denizci millet yetiştirmek kabiliyetindedir" sözünün ardından vurguladığı ünlü ilke hangisidir?', 'Denizciliği Türk\'ün büyük milli ülküsü olarak düşünmeli ve onu az zamanda başarmalıyız', ['Ordular ilk hedefiniz Akdeniz\'dir ileri diyerek bütün kıyı kalelerini tahkim etmeliyiz', 'Yurtta sulh cihanda sulh ilkesi gereği tüm açık deniz filolarını kıyı savunmasına çekmeliyiz', 'Demiryolu ağını tamamlamadan deniz ticaretine hiçbir kamu kaynağı aktarmamalıyız'], 'Atatürk bu tarihi konuşmasında "Denizciliği, Türk\'ün büyük milli ülküsü olarak düşünmeli ve onu az zamanda başarmalıyız" diyerek Cumhuriyet denizcilik vizyonunu özetlemiştir.'),
  ('Osmanlı dönemindeki "İdare-i Mahsusa" ve "Osmanlı Seyr-i Sefain İdaresi" kurumlarının Cumhuriyet\'in ilanından sonra dönüştürülmesiyle oluşturulan ulusal deniz taşımacılığı idaresi hangisidir?', 'Türkiye Seyr-i Sefain İdaresi', ['Şirket-i Hayriye Ortaklığı', 'Haliç Vapurları Kumpanyası', 'İzmir Körfez İşletmesi'], 'Cumhuriyet kurulduktan sonra Osmanlı Seyr-i Sefain İdaresi millileştirilip yeniden yapılandırılarak Türkiye Seyr-i Sefain İdaresi adını almış, daha sonra Devlet Denizyolları\'na dönüşmüştür.'),
  ('Cumhuriyet Donanması\'nın en büyük gemisi olan Yavuz Zırhlısı\'nın onarımı ve yeni donanma üssü oluşturulması amacıyla 1920\'lerin ortalarında İzmit Körfezi\'nde kurulan ana askeri tersane hangisidir?', 'Gölcük Tersanesi', ['Taşkızak Tersanesi', 'Gelibolu Tersanesi', 'Sinop Tersanesi'], 'Lozan gereği Boğazlar askersizleştirildiği için Marmara\'nın korunaklı doğu ucundaki Gölcük, Cumhuriyet Donanması\'nın ana üssü ve tersanesi olarak seçilip geliştirilmiştir.'),
  ('Savarona yatı alınmadan önce Mustafa Kemal Atatürk\'ün yurt içi kıyı gezilerinde ve yabancı devlet konuklarını ağırlamakta kullandığı, Osmanlı\'dan miras kalan tarihi yat hangisidir?', 'Ertuğrul Yatı', ['Nusret Gemisi', 'Bandırma Vapuru', 'Mesudiye Zırhlısı'], 'II. Abdülhamid döneminde İngiltere\'de yaptırılan Ertuğrul Yatı, Cumhuriyet döneminde 1937 yılına kadar Atatürk\'ün Cumhurbaşkanlığı yatı olarak hizmet vermiştir.'),
  ('4 Nisan 1953 tarihinde NATO tatbikatından dönerken Çanakkale Boğazı Nara Burnu açıklarında İsveç bandıralı Naboland şilebiyle çarpışarak batan ve 81 denizcimizin şehit olduğu denizaltımız hangisidir?', 'TCG Dumlupınar', ['TCG Atılay', 'TCG Ülker', 'TCG Refah'], 'Nara Burnu açıklarında batan Dumlupınar denizaltısında mahsur kalan denizcilerimizin "Vatan sağ olsun" sözleri Türk denizcilik tarihine silinmez biçimde kazınmıştır.'),
  ('1773 yılında Cezayirli Gazi Hasan Paşa öncülüğünde "Mühendishane-i Bahri-i Hümayun" adıyla kurulan köklü eğitim kurumu, Cumhuriyet denizciliğinde hangi kurumların temelini oluşturmuştur?', 'Deniz Harp Okulu ve İstanbul Teknik Üniversitesi Denizcilik Fakültesi', ['Ankara Üniversitesi Siyasal Bilgiler Fakültesi ve Hukuk Mektebi', 'Galatasaray Sultanisi ve Darülfünun Edebiyat Medresesi', 'Sanayi-i Nefise Mektebi ve Mülkiye Mühendis Mektebi'], 'Kasımpaşa\'da kurulan Mühendishane-i Bahri-i Hümayun, hem Türk Deniz Harp Okulu\'nun hem de İTÜ başta olmak üzere teknik ve denizcilik yükseköğretiminin tarihsel çekirdeğidir.'),
  ('Cumhuriyet döneminde sivil ticaret filolarına güverte ve makine zabiti yetiştirmek amacıyla 1909\'da kurulan "Milli Ticaret-i Bahriye Kaptan ve Çarkçı Mektebi" geliştirilerek hangi adla yükseköğretim kurumuna dönüştürülmüştür?', 'Yüksek Denizcilik Okulu', ['Deniz Astsubay Meslek Okulu', 'Bahriye Sanayi Mektebi', 'Tersane Çıraklık Enstitüsü'], 'Cumhuriyet\'in kabotaj hamlesine paralel olarak sivil deniz ticaretine nitelikli kaptan ve başmühendis yetiştiren kurum Yüksek Denizcilik Okulu adını almış, sonradan İTÜ Denizcilik Fakültesi olmuştur.'),
  ('Cumhuriyet\'in ilk on beş yılında hem üç tarafı denizlerle çevrili kıyıların iç bölgelere bağlanması hem de dış ticaretin canlandırılması için ulaştırma politikasında hangi bütünleşik yaklaşım izlenmiştir?', 'Demiryolu hatlarının Samsun, Mersin, İzmir ve Zonguldak gibi limanlara ulaştırılması', ['Yalnızca kara şoselerine yatırım yapılarak liman inşaatlarının tamamen durdurulması', 'Bütün liman işletmelerinin kırk dokuz yıllığına yabancı şirketlere kiralanması', 'İç Anadolu\'daki nehirlerin kanallarla birbirine bağlanarak gemi yüzdürülmesi'], 'Cumhuriyet yönetimi, iç bölgelerdeki tarım ve maden ürünlerini (örneğin Ergani bakırı ve Zonguldak kömürünü) limanlara ulaştırmak için demiryollarını liman kentleriyle birleştirmiştir.'),
  ('1909 yılında vatansever halkın bağışlarıyla Türk deniz gücünü takviye etmek amacıyla kurulan ve Cumhuriyet öncesinde ulusal denizcilik bilincini uyandıran sivil toplum kuruluşu hangisidir?', 'Donanma-yı Osmani Muavenet-i Milliye Cemiyeti', ['Hilal-i Ahmer Yardım Cemiyeti', 'Müdafaa-i Hukuk Cemiyeti', 'İttihat ve Terakki Cemiyeti'], 'Kısaca Donanma Cemiyeti olarak bilinen bu kuruluş, halktan topladığı bağışlarla Muavenet-i Milliye, Yadigar-ı Millet gibi muhripleri ve Sultan Osman dretnotunu sipariş ettirmiştir.'),
  ('Kabotaj Kanunu\'nun yürürlüğe girmesi Cumhuriyet ekonomisinde yerli sermaye ve istihdam açısından doğrudan hangi sonucu doğurmuştur?', 'Liman işçiliğinden armatörlüğe kadar deniz ticaret gelirlerinin ülke içinde kalmasını', ['Yabancı bayraklı gemilerin açık denizlerden Türk limanlarına yük getirmesinin yasaklanmasını', 'Türkiye\'nin Akdeniz ve Karadeniz\'deki bütün gümrük vergilerini sıfırlamasını', 'Bütün özel Türk şileplerinin kapatılarak yalnızca askeri gemilerle yük taşınmasını'], 'Kabotaj Kanunu yabancı gemilerin uluslararası limanlardan yük getirmesini değil, iki Türk limanı arasındaki iç taşımacılığı yabancılara kapatarak yerli denizcilik sektörünü ve istihdamı büyütmüştür.'),
  ('1923 yılında toplanan İzmir İktisat Kongresi\'nde alınan "Misak-ı İktisadi" ve kongre kararlarında denizcilik alanında öne çıkan temel talep ne olmuştur?', 'Kendi limanlarımızda kabotaj istiklali sağlanması ve deniz ticaret filomuzun geliştirilmesi', ['Süveyş ve Panama kanallarından Türkiye\'ye ortaklık hissesi satın alınması', 'Karadeniz\'deki bütün balıkçılık haklarının komşu devletlere devredilmesi', 'Yerli tersanelerin kapatılarak gemilerin yalnızca hazır ithal edilmesi'], 'Şubat-Mart 1923\'te toplanan İzmir İktisat Kongresi, henüz Lozan imzalanmadan önce kendi sularımızda kabotaj bağımsızlığının kazanılmasını temel ekonomik hedeflerden biri ilan etmiştir.'),
  ('Türkiye\'nin üç tarafını çevreleyen denizler ile Türk Boğazlarında seyir güvenliğini sağlamak, deniz kazalarında can ve mal kurtarmak amacıyla faaliyet gösteren kamu kuruluşunun temel görevi hangi tarihsel mirasa dayanır?', 'Tahlisiye (Can Kurtarma) ve Fenerler İdaresi hizmetlerinin millileştirilmesine', ['Düyun-u Umumiye bünyesindeki Tuz ve Tütün Tekeli muhafaza memurluğuna', 'Hicaz Demiryolu İdaresi\'nin Kızıldeniz iskele muhafız birliklerine', 'Osmanlı Enderun Mektebi içindeki saray kayıkçıları teşkilatına'], 'Osmanlı\'da yabancı imtiyaz sahiplerince de işletilen Fenerler ve Tahlisiye (Gemi Kurtarma) idareleri Cumhuriyet döneminde millileştirilerek çağdaş kıyı emniyeti teşkilatına dönüştürülmüştür.'),
  ('Süveyş Kanalı ile Türk Boğazlarının (İstanbul ve Çanakkale) uluslararası deniz hukuku açısından taşıdığı en temel coğrafi fark nedir?', 'Süveyş Kanalı\'nın insan yapımı yapay bir kanal, Türk Boğazlarının ise doğal su yolu olması', ['Süveyş Kanalı\'nın iki gölü, Türk Boğazlarının ise iki okyanusu birbirine bağlaması', 'Süveyş Kanalı\'nın tatlı su, Türk Boğazlarının ise tamamen tuzlu su içermesi', 'Süveyş Kanalı\'nın uluslararası sular, Türk Boğazlarının ise açık deniz sayılması'], 'Süveyş ve Panama insan eliyle açılmış yapay kanallar iken, İstanbul ve Çanakkale Boğazları iki denizi birbirine bağlayan doğal su yollarıdır ve Montrö Sözleşmesi\'ne tabidir.'),
  ('1869\'da Süveyş Kanalı\'nın açılması Osmanlı İmparatorluğu\'nun Arap Yarımadası ve Kızıldeniz\'deki hakimiyeti açısından kısa vadede hangi askeri kolaylığı sağlamıştır?', 'İstanbul\'dan Yemen ve Hicaz bölgesine deniz yoluyla asker sevkiyatını hızlandırmasını', ['Osmanlı donanmasının Cebelitarık üzerinden Atlas Okyanusu\'na açılabilmesini', 'Basra Körfezi\'ndeki İngiliz ticaret gemilerinin tamamen bölgeden çıkarılmasını', 'Mısır\'ın Hidivlik statüsünün kaldırılarak doğrudan merkezden yönetilmesini'], 'Süveyş Kanalı sayesinde Osmanlı merkezi yönetimi, isyanların sık yaşandığı uzak Yemen ve Hicaz vilayetlerine İstanbul\'dan doğrudan vapurlarla birlik ve ikmal gönderebilme imkanı bulmuştur.'),
  ('Çanakkale Savaşı sırasında 25 Nisan 1915\'ten itibaren kara muharebeleri de başlayınca Boğaz\'dan Marmara\'ya sızan İngiliz denizaltısı E11 tarafından 8 Ağustos 1915\'te Bolayır açıklarında torpillenerek batırılan ve Çanakkale cephesine cephane taşıyan Osmanlı zırhlısı hangisidir?', 'Barbaros Hayreddin Zırhlısı', ['Yavuz Sultan Selim Zırhlısı', 'Hamidiye Kruvazörü', 'Ertuğrul Fırkateyni'], 'Almanya\'dan 1910\'da satın alınan Barbaros Hayreddin zırhlısı, Çanakkale\'de iç takviye ateş desteği verirken ve cephane taşırken İngiliz E11 denizaltısı tarafından batırılmış ve 253 denizcimiz şehit olmuştur.'),
  ('Çanakkale Boğazı savunmasında yalnız mayın hatlarının değil kıyıdaki sahra topçu bataryalarının da hayati rol oynamasının nedeni nedir?', 'Mayın tarama gemilerini ateş altına alarak Nusret ve diğer gemilerin döktüğü mayınların temizlenmesini önlemesi', ['Uzak mesafeden İtilaf uçak gemilerini batırarak hava keşfini imkansız kılması', 'Denizaltıların su altındaki periskoplarını on beş kilometreden vurabilmesi', 'Boğaz akıntısının yönünü değiştirerek gemileri kayalıklara sürüklemesi'], 'Türk hareketli obüs ve kıyı bataryaları, İtilaf donanmasının zırhlılarını olduğu kadar mayın tarama gemilerini de sürekli ateş altında tutarak mayın hatlarının temizlenmesine izin vermemiştir.'),
  ('İklim değişikliği ve şiddetli kuraklık dönemleri Süveyş Kanalı\'nı doğrudan etkilemezken Panama Kanalı\'ndaki gemi geçiş sayısını neden kısıtlayabilmektedir?', 'Panama Kanalı\'ndaki havuz sisteminin gemileri yükseltip indirmek için yağmur sularıyla beslenen tatlı su göllerine bağımlı olması', ['Süveyş Kanalı\'nın her iki ucunda buzul erimelerinden gelen nehirlerin bulunması', 'Panama Kanalı\'nda gemilerin yalnızca rüzgar gücüyle çalışan yelkenlerle çekilmesi', 'Süveyş Kanalı\'nın yer altındaki kapalı tüneller içinden geçerek buharlaşmayı önlemesi'], 'Panama Kanalı\'nda her gemi geçişinde Gatun ve Alajuela tatlı su göllerinden milyonlarca metreküp su okyanusa boşaldığı için kuraklık dönemlerinde su seviyesi düşmekte ve geçiş su çekimi sınırlandırılmaktadır.'),
  ('2015 yılında Mısır\'ın "Yeni Süveyş Kanalı" projesiyle mevcut kanalın belirli bir bölümüne paralel ikinci bir şerit açmasının temel amacı ne olmuştur?', 'Gemilerin bekleme süresini azaltıp karşılıklı çift yönlü geçiş kapasitesini artırmak', ['Kızıldeniz\'den Akdeniz\'e geçen balık türlerinin göçünü tamamen durdurmak', 'Kanalı deniz seviyesinden çıkararak havuzlu ve kapaklı sisteme dönüştürmek', 'Yalnızca askeri uçak gemilerine tahsis edilmiş gizli bir su yolu kurmak'], 'Mısır, 2015\'te tamamladığı paralel kanal ve derinleştirme projesiyle konvoy bekleme sürelerini kısaltmış ve kanalın günlük gemi geçiş kapasitesini yükseltmiştir.'),
  ('1928 yılında kabul edilen Yeni Türk Harfleri\'nin ardından gemi bordalarındaki isimlerin Latin esaslı Türk alfabesiyle yazılması ve denizcilik terimlerinin Türkçeleştirilmesi çalışmaları hangi dönemin kültür devrimiyle bütünleşmiştir?', 'Atatürk Dönemi Türk İnkılabı', ['Tanzimat Fermanı Dönemi', 'Birinci Meşrutiyet Dönemi', 'Lale Devri Islahatları'], 'Harf ve Dil İnkılabı ile birlikte Türk ticaret ve savaş gemilerinin isimleri yeni Türk harfleriyle yazılmış, denizcilik eğitim ve mevzuat dili sadeleştirilmiştir.'),
  ('1833 Hünkar İskelesi\'nden 1936 Montrö Sözleşmesi\'ne uzanan yaklaşık bir asırlık Boğazlar diplomasisi incelendiğinde Türkiye\'nin güvenliği açısından çıkarılabilecek en temel tarihsel ders nedir?', 'Boğazlar üzerinde tam ulusal egemenlik ve caydırıcı savunma gücü bulunmadıkça kalıcı güvenliğin sağlanamayacağı', ['Boğazların güvenliğinin yalnızca yabancı büyük güçlerin oluşturduğu komisyonlara bırakılarak korunabileceği', 'Boğazların uluslararası ticaret gemilerine tamamen kapatılmasının ülke ekonomisini zenginleştireceği', 'Karadeniz ve Akdeniz arasındaki su yolunun askeri ve siyasi öneminin zamanla ortadan kalktığı'], 'Lozan\'daki silahsızlandırma ve komisyon deneyimi ortak uluslararası garantilerin kriz anında yetersiz kaldığını göstermiş; Montrö ile kurulan tam Türk egemenliği ve askeri kontrol ise kalıcı istikrar sağlamıştır.'),
  ('Bir araştırmacı 1841 Londra Boğazlar Sözleşmesi ile 1936 Montrö Boğazlar Sözleşmesi\'ni barış zamanında yabancı savaş gemilerinin geçişi bakımından karşılaştırdığında hangi doğru sonuca ulaşır?', '1841\'de barışta yabancı savaş gemilerine mutlak kapalılık varken, 1936\'da Türkiye\'nin denetiminde sıkı tonaj ve süre sınırlamalı geçiş rejimi vardır', ['1841\'de tüm savaş gemileri sınırsız geçebilirken, 1936\'da ticaret gemileri dahil tüm geçişler yasaklanmıştır', 'Her iki sözleşmede de Boğazların yönetimi merkezi Cenevre\'de bulunan yabancı bir komisyona verilmiştir', '1841\'de yalnızca uçak gemilerine izin verilirken, 1936\'da yalnızca nükleer denizaltılara serbestlik tanınmıştır'], '1841 Londra Sözleşmesi barış zamanında Boğazları tüm yabancı savaş gemilerine kapatırken, Montrö Sözleşmesi bildirim, tonaj, gemi türü ve Karadeniz\'de kalış süresi (21 gün) kısıtlamalarıyla Türkiye denetiminde dengeli bir rejim kurmuştur.'),
  ('Çanakkale Deniz Savaşları sırasında Anadolu yakasında Boğaz girişini ve Erenköy Koyu\'nu ateş altına alarak İtilaf zırhlılarına ağır hasar verdiren ünlü Türk tabyalarından biri hangisidir?', 'Dardanos Tabyası', ['Aziziye Tabyası', 'Kanlı Tabya', 'Şıpka Geçidi Tabyası'], 'Hasan ve Mevsuf Beylerin şehit düştüğü Anadolu yakasındaki Dardanos Bataryası (Hasan-Mevsuf Şehitliği), Rumeli\'deki Mecidiye ve Hamidiye tabyalarıyla birlikte 18 Mart savunmasının kilit noktalarından biri olmuştur.'),
  ('Londra\'dan yola çıkıp Hindistan\'ın Mumbai (Bombay) Limanı\'na giden bir yük gemisi Ümit Burnu yerine Süveyş Kanalı rotasını kullandığında yaklaşık ne kadarlık bir mesafe kısalmasından yararlanır?', 'Yaklaşık yüzde kırk oranında binlerce deniz millik büyük bir mesafe tasarrufundan', ['Sadece yüz deniz millik çok küçük ve önemsiz bir kıyı kestirmesinden', 'Atlas Okyanusu\'ndan Büyük Okyanus\'a geçerek dünyayı ters yönden dolaşmaktan', 'Cebelitarık Boğazı\'na hiç uğramadan Kuzey Buz Denizi üzerinden gitmekten'], 'Londra-Mumbai hattı Ümit Burnu dolaşıldığında yaklaşık 10.800 deniz mili iken, Süveyş Kanalı üzerinden yaklaşık 6.300 deniz miline düşerek %40\'tan fazla kısalmaktadır.'),
  ('Cumhuriyet\'in ilk yıllarında Türk deniz ticaret filosunun yaşlı gemilerden oluşmasına rağmen Kabotaj Kanunu\'nun kararlılıkla uygulanması uzun vadede hangi gelişmeyi teşvik etmiştir?', 'Yerli armatörlüğün doğmasını, tersaneciliğin gelişmesini ve Türk denizcilerinin uzmanlaşmasını', ['Türk limanları arasındaki bütün yolcu ve yük taşımacılığının kalıcı olarak sona ermesini', 'Karadeniz ve Ege kıyılarındaki liman şehirlerinin iç bölgelere taşınmasını', 'Yabancı denizcilik kumpanyalarının Türkiye\'deki demiryolu hatlarını satın almasını'], 'Başlangıçta gemi ve personel sıkıntısı yaşansa da Kabotaj Kanunu koruyucu bir şemsiye oluşturarak Türk armatörlerin gemi almasını, devletin Denizyolları\'nı büyütmesini ve binlerce Türk gencinin denizcilik mesleğine yönelmesini sağlamıştır.'),
];
